INSERT INTO public.exam_tactics (topic_tag, title_tr, tactic_tr, examples_tr) VALUES
  ('articles', $t0a$Artikelde İlk Bahis mi, Bilinen Şey mi? Testi$t0a$, $t0b$Boşluktaki ismin sayılabilir tekil mi, sayılamayan/çoğul mu olduğuna ve cümlede YENİ mi yoksa BİLİNEN bir şeyden mi bahsedildiğine bak. İsim ilk kez geçiyorsa veya bir kategoriden rastgele BİR örnek belirtiliyorsa (sayılabilir tekil isimle) a/an kullanılır. İsim daha önce bahsedilmiş, bağlamdan TEK olduğu anlaşılan, bir "of" öbeğiyle belirlenmiş (the capital of France) veya en üstünlük bildiren bir sıfatla (the most, the best, the only) kullanılıyorsa the gelir — en üstünlük sıfatlarından önce the'nin unutulması YDS'nin klasik tuzaklarından biridir. İsim sayılamayan bir isim olarak GENEL bir anlamda kullanılıyorsa veya çoğul bir isim bir KATEGORİYİ bütün olarak temsil ediyorsa (Dogs are loyal animals = genel olarak köpekler) hiç artikel kullanılmaz; aynı isim belirli bir grubu işaret ediyorsa (The dogs in this shelter are friendly = bu barınaktaki belirli köpekler) the gerekir.$t0b$, ARRAY[$t0c$"__________ Amazon is the longest river in __________ world." Özel coğrafi isimlerden nehir adları (the Amazon, the Nile) ve dünya gibi TEK olan kavramlar (the world, the universe) her zaman the alır — doğru cevap her iki boşluk için de "the"dır; sıradan ülke isimleriyle (France, Turkey) ise genellikle artikel kullanılmaz.$t0c$, $t0d$"__________ information you gave me was extremely useful, but __________ information in general is often unreliable online." İlk boşlukta "you gave me" ile belirlenmiş, BİLİNEN bir bilgiden bahsedildiği için "The" gerekir; ikinci boşlukta ise "information" genel bir kavram olarak (sayılamayan isim, genelleme) kullanıldığı için hiç artikel gerekmez — aynı isim aynı cümlede hem belirli hem genel anlamda geçebilir.$t0d$]),
  ('past-simple-vs-continuous', $t1a$Kesintiye Uğrayan mı, Kesen mi? when/while Testi$t1a$, $t1b$Cümlede iki eylem varsa, hangisinin DAHA UZUN SÜRELİ/ARKA PLANDA devam ettiğine, hangisinin ise ANİDEN araya girip onu KESTİĞİNE bak: devam eden, arka plandaki eylem past continuous (was/were + -ing) alır, onu kesen ani/kısa eylem past simple alır. "while" genellikle iki eylemden en az birinin SÜREGELEN olduğunu işaret eder ve past continuous ile birlikte kullanılır ("While I was cooking, the phone rang"); "when" ise genellikle ANİ eylemi tanıtır ve past simple ile gelir. Eğer iki eylem SIRAYLA, birbiri bitince diğeri başlayarak gerçekleşiyorsa (önce X oldu, sonra Y oldu) ikisi de past simple alır — past continuous burada YANLIŞTIR çünkü sıralı/tamamlanmış eylemler arka plan eylemi değildir. Tekrarlanan geçmiş alışkanlıklar için de past continuous DEĞİL, past simple veya "used to" kullanılır.$t1b$, ARRAY[$t1c$"While the workers __________ (repair) the bridge, a sudden storm __________ (force) them to stop." Köprüyü tamir etme eylemi arka planda SÜREN bir eylemdir → "were repairing"; fırtınanın araya girmesi ANİ ve kısa bir eylemdir → "forced". Doğru cevap: "were repairing / forced".$t1c$, $t1d$"As soon as she __________ (arrive) at the station, she __________ (call) her mother." Burada iki eylem ARKA ARKAYA, biri bitince diğeri gerçekleşiyor (önce vardı, sonra aradı) — aralarında "kesme" ilişkisi yok, bu yüzden ikisi de past simple alır: "arrived / called"; "was arriving" kullanmak yanlıştır çünkü varış arka planda süren bir eylem değildir.$t1d$]),
  ('see-someone-do-vs-doing', $t2a$Tam mı, Yarım mı? Algı Fiillerinde do/doing Seçimi$t2a$, $t2b$see, hear, watch, notice, feel gibi algı fiillerinden sonra nesne + FİİL (bare infinitive, to'suz) geliyorsa, eylemin BAŞINDAN SONUNA KADAR TAMAMINI gözlemlediğimiz anlatılır ("I saw him cross the street" = karşıya geçişinin tamamını gördüm). Aynı yapıda nesne + fiil-ING kullanılırsa, eylemin SÜRERKEN, yani YARIM bir anında yakalandığı anlatılır ("I saw him crossing the street" = geçerken, ortasında bir anda gördüm, geçişi tamamlayıp tamamlamadığını bilmiyoruz). Cümlede "for a while", "as I passed by", "when I looked out" gibi KISA BİR AN'a veya SÜREKLİLİĞE işaret eden ifadeler varsa -ing formu tercih edilir; eylemin SONUCU/TAMAMLANMASI net bir şekilde vurgulanıyorsa (örneğin sonrasında ne olduğu anlatılıyorsa) bare infinitive doğrudur.$t2b$, ARRAY[$t2c$"I saw the thief __________ (steal) the wallet and then run away." Cümlenin devamında "run away" (kaçtı) ile hırsızlığın TAMAMLANDIĞI ve sonucunun anlatıldığı belli oluyor → doğru cevap bare infinitive "steal"dir, eylemin başından sonuna kadarı gözlemlenmiştir.$t2c$, $t2d$"As I walked past the classroom, I heard the students __________ (sing) a song." Burada sadece yoldan geçerken, şarkının SÜRERKEN bir anına kulak misafiri olunmuş, başlangıcı veya bitişi bilinmiyor → doğru cevap -ing formu "singing"dir.$t2d$]),
  ('separable-inseparable-phrasal-verbs', $t3a$Zamir Araya Girer mi? Ayrılabilir Phrasal Verb Testi$t3a$, $t3b$Bir phrasal verb'ün ayrılabilir mi ayrılamaz mı olduğunu anlamanın en kesin yolu nesnenin ZAMİR olduğu bir cümle kurmaktır: ayrılabilir bir phrasal verb'de (turn off, give up, pick up, work out, call off) nesne isim ise fiil+parçacığın öncesine veya arasına girebilir ("turn off the light" / "turn the light off"), AMA nesne ZAMİR (it, him, her, them) ise MUTLAKA araya girmek ZORUNDADIR — "turn off it" gibi bir kullanım kesinlikle yanlıştır, doğrusu "turn it off"tur. Ayrılamaz phrasal verb'lerde (look after, come across, run into, deal with, get over) nesne ne isim ne de zamir olsun, HER ZAMAN fiil+parçacık grubunun sonrasına gelir ve asla araya giremez — "look the children after" veya "look them after" yanlıştır, doğrusu "look after them"dir.$t3b$, ARRAY[$t3c$"She had to cancel the meeting, so she decided to call __________ off." Boşluktaki nesne "the meeting"in yerini tutan bir zamirdir (it) ve "call off" ayrılabilir bir phrasal verb olduğu için zamir kullanıldığında araya girmesi ZORUNLUDUR → doğru cevap "it" olup "call it off" şeklinde kurulmalıdır, "call off it" yanlıştır.$t3c$, $t3d$"I unexpectedly __________ an old friend of mine while shopping downtown." "run into" (rastlamak) ayrılamaz bir phrasal verb'dür, nesne ister isim ister zamir olsun her zaman grubun sonrasına gelir; cümle gramer olarak doğru tamamlanır: "ran into" — burada ayırma denemek ("run an old friend into") anlamsız ve yanlış olurdu.$t3d$]),
  ('be-vs-get-passive', $t4a$Nötr mü, Ani mi? be passive / get passive Ayrımı$t4a$, $t4b$Cümlede edilgen bir yapı kurulacağında, anlatılan durum NÖTR, RESMİ ve SÜREGELEN bir gerçekse (bir kural, bir açıklama, bir rapor) be + past participle (be passive) tercih edilir ("The report is reviewed every month"). Ancak durum ANİ, BEKLENMEDİK, genellikle OLUMSUZ veya günlük konuşma diline ait bir DEĞİŞİMİ anlatıyorsa (bir şeyin kırılması, kaybolması, şaşırtması gibi) get + past participle (get passive) kullanılır ("My phone got stolen last night"). YDS/YÖKDİL'de resmi/akademik metinlerde be passive, günlük diyalog veya anlatı parçalarında ani bir olayı anlatan cümlelerde get passive aranmalıdır; "suddenly", "unexpectedly", "accidentally" gibi zarflarla birlikte get passive kullanılması çok daha doğaldır.$t4b$, ARRAY[$t4c$"According to the company policy, all expenses __________ (must/report) within thirty days." Burada resmi bir kural/politika anlatıldığı için nötr be passive tercih edilir → doğru cevap "must be reported"tur.$t4c$, $t4d$"The old bridge __________ (build) in the 1800s and is still used today." Burada tarihi, nötr bir bilgi aktarılıyor, ani/beklenmedik bir durum yok → doğru cevap sade be passive "was built"tir; buraya "got built" yazmak günlük/gayriresmî bir ton katar ve resmi-tarihi bir anlatımla uyuşmaz.$t4d$]),
  ('phrasal-verbs', $t5a$Parçaları Değil, Bütünü Oku: Phrasal Verb Mantığı$t5a$, $t5b$Phrasal verb'lerin çoğunda fiil ile tek tek kelimelerin anlamı sorudan tamamen BAĞIMSIZDIR — "give up" (vazgeçmek), "look up" (araştırmak/bulmak), "run out of" (tükenmek) gibi kalıpları kelime kelime çevirmeye çalışmak yanıltıcıdır; bunlar TEK bir kelime gibi ezberlenmelidir. Sınavlarda phrasal verb soruları genellikle İKİ şekilde karşımıza çıkar: (1) boşluğa uygun phrasal verb'ü tamamlama, (2) cümledeki bir phrasal verb'ün ANLAMINI tek kelimelik bir eşanlamlıyla (synonym) değiştirme — bu tür sorularda phrasal verb'ü parçalarına ayırıp tahmin etmek yerine, bağlamdaki olayın SONUCUNA bakıp hangi tek kelimenin (örneğin "postpone", "abandon", "discover") o sonucu ifade ettiğini bulmak gerekir. Aynı fiil farklı parçacıklarla TAMAMEN farklı anlamlara gelebilir ("give up" = vazgeçmek, "give in" = teslim olmak, "give away" = ifşa etmek/bağışlamak), bu yüzden parçacığı değiştirip anlamı sabit tutmak büyük bir hatadır.$t5b$, ARRAY[$t5c$"Due to the heavy snowfall, the flight was __________ until further notice." Cümlenin anlamı uçuşun ERTELENDİĞİni gösteriyor → doğru cevap "put off" veya "postponed"dur (aynı anlam); "called off" (tamamen iptal etme) ise "until further notice" (daha sonra haber verilecek) ifadesiyle çelişir çünkü bu ifade uçuşun İLERİDE gerçekleşeceğini ima eder, tamamen iptali değil.$t5c$, $t5d$"The committee decided to __________ the proposal after months of criticism." Bağlamda aylar süren eleştiriden SONRA teklifin tamamen TERK EDİLDİĞİ anlatılıyor → doğru cevap "give up on" ya da "abandon" anlamına gelen bir phrasal verb'dür ("drop"); "give away" (ifşa etmek/bağışlamak) burada anlamsız kaçar çünkü parçacık farklı olduğu için fiilin anlamı tamamen değişmiştir.$t5d$]),
  ('future-continuous-perfect', $t6a$O Anda Sürüyor mu, Bitmiş mi? Future Continuous/Perfect Testi$t6a$, $t6b$Cümlede gelecekteki BELİRLİ bir ana ("at 9 PM tomorrow", "this time next week") işaret edilip o anda bir eylemin HALA SÜRMEKTE olacağı anlatılıyorsa future continuous (will be + -ing) kullanılır ("At 9 PM, I will be flying to Istanbul" = o saatte uçakta olacağım, eylem sürüyor). Cümlede "by" + gelecek zaman ifadesi ("by next year", "by the time she arrives") varsa ve bir eylemin o zamandan ÖNCE TAMAMLANMIŞ olacağı anlatılıyorsa future perfect (will have + past participle) kullanılır ("By next year, I will have graduated" = mezuniyet o zamandan önce bitmiş olacak). "by the time + present simple cümlecik" kalıbı YDS'nin klasik future perfect tetikleyicisidir; "at + belirli an" ise future continuous'un işaretidir. İkisini karıştırmamak için kendine şunu sor: o anda eylem HALA mı oluyor (continuous) yoksa o ana kadar BİTMİŞ mi olacak (perfect)?$t6b$, ARRAY[$t6c$"By the time the guests arrive, she __________ (finish) cooking dinner." "by the time" + present simple kalıbı, yemek pişirme eyleminin misafirler gelmeden ÖNCE tamamlanmış olacağını gösterir → doğru cevap future perfect "will have finished"tir.$t6c$, $t6d$"Don't call me at 8 PM, I __________ (have) dinner with my family at that time." "at that time" (o saatte) ifadesi belirli bir anı işaret ediyor ve yemek yeme eyleminin o anda HALA SÜRECEĞİ anlatılıyor → doğru cevap future continuous "will be having"dir, future perfect burada yanlış olurdu çünkü eylemin bitmiş olması değil, o anda sürüyor olması vurgulanıyor.$t6d$]),
  ('future-going-to-will', $t7a$Önceden mi Planlandı, Anında mı Karar Verildi? going to/will Testi$t7a$, $t7b$Cümlede bir eylemin konuşmadan ÖNCE planlandığına dair bir ipucu varsa ("I have already decided", "We have booked...", bir niyet daha önce kurulmuşsa) going to kullanılır; aynı şekilde gözle görülür bir KANIT varsa ("Look at those clouds" gibi somut bir işaret) going to ile tahmin yapılır ("It's going to rain" = bulutlara bakarak). Konuşma ANINDA, o an alınan SPONTANE bir karar varsa ("The phone is ringing, I'll answer it") veya bir SÖZ/TEKLİF/RİCA söz konusuysa ("I'll help you", "Will you marry me?") will kullanılır; ayrıca "I think/believe/suppose" gibi KİŞİSEL GÖRÜŞE dayalı bir tahmin yapılıyorsa (somut kanıt değil, fikir) yine will tercih edilir ("I think it will rain tomorrow"). Cümlede somut bir kanıttan mı yoksa kişisel bir görüşten mi bahsedildiğine dikkat etmek, going to ile will arasındaki en sık sınav tuzağını çözer.$t7b$, ARRAY[$t7c$"Look out! That glass is right at the edge of the table — it __________ (fall)!" Konuşan kişi o an GÖRDÜĞÜ somut bir kanıta (bardağın kenarda olması) dayanarak tahmin yapıyor → doğru cevap "is going to fall"dır.$t7c$, $t7d$"I'm not sure about the weather, but I think it __________ (be) sunny this weekend." Burada somut bir kanıt değil, kişisel bir GÖRÜŞ/TAHMİN ("I think") söz konusu → doğru cevap "will be"dir; "is going to be" burada daha az doğaldır çünkü gözle görülür bir kanıttan değil, fikirden bahsediliyor.$t7d$]),
  ('subject-verb-agreement-nouns', $t8a$Görünüşe Değil Türüne Bak: Özne-Yüklem Uyumu Testi$t8a$, $t8b$Bir isim -s ile bitse bile ya da çoğul GÖRÜNSE bile, sayılamayan bir isimse (news, information, advice, furniture, equipment) HER ZAMAN tekil fiil alır ("The news is shocking", "information is") — bu isimlerin sonunda -s olması onları çoğul yapmaz. Tam tersine bazı isimler SADECE çoğul formda bulunur ve asla tekil kullanılmaz, bu yüzden her zaman çoğul fiil alır (clothes, trousers, scissors, glasses, jeans, people) — "people is" değil "people are" doğrudur. Toplu isimler (team, family, government, committee) bir BÜTÜN olarak düşünülürse tekil, üyelerinin AYRI AYRI davrandığı vurgulanırsa çoğul fiil alabilir — YDS genellikle bunu bağlamdan belli eder ("The team is playing well" = bütün olarak / "The team are arguing among themselves" = üyeler ayrı ayrı). Özne ile fiil arasına giren "as well as", "together with", "along with" gibi ifadeler ÖZNEYİ ÇOĞULLAŞTIRMAZ — fiil hâlâ asıl özneye göre çekimlenir.$t8b$, ARRAY[$t8c$"The information the journalist gathered __________ (seem) quite reliable." "information" sayılamayan bir isimdir, çoğul görünmese de her zaman tekil fiil alır → doğru cevap "seems"tir.$t8c$, $t8d$"The manager, together with his three assistants, __________ (be) responsible for the final decision." "together with his three assistants" özneyi çoğullaştırmaz, asıl özne tekil olan "the manager"dır → doğru cevap "is"dir, "are" burada yaygın bir tuzaktır.$t8d$]),
  ('comparatives-superlatives', $t9a$Hece Sayısına ve Düzensizlere Dikkat: Karşılaştırma Testi$t9a$, $t9b$Tek heceli sıfatlara (tall, fast, big) ve bazı iki heceli, -y ile biten sıfatlara (happy→happier, easy→easier) -er/-est eklenir; iki heceden uzun sıfatlara (beautiful, interesting, difficult) more/most eklenir — bu kuralı karıştırıp "more taller" veya "beautifuler" gibi İKİ karşılaştırma işaretini birden kullanmak (double comparative hatası) YDS/YÖKDİL'in klasik yanlış şık tuzağıdır. Düzensiz sıfatları ezbere bilmek gerekir: good→better→best, bad→worse→worst, far→farther/further→farthest/furthest, little→less→least, many/much→more→most. Karşılaştırma yapılan cümlede "than" varsa mutlaka KARŞILAŞTIRMA formu (comparative, -er/more) gelir, "the" ile başlayan üstünlük cümlelerinde ise SÜPERLATİF (-est/most) formu aranır. "the + comparative..., the + comparative..." kalıbı ("The more you practice, the better you get") iki şeyin birlikte ARTTIĞINI/AZALDIĞINI anlatan özel bir yapıdır ve sınavlarda sıkça çeldirici olarak kullanılır.$t9b$, ARRAY[$t9c$"This year's exam was __________ than last year's, but it was far from being __________ exam students have ever taken." İlk boşlukta "than" olduğu için karşılaştırma formu gerekir → "more difficult"; ikinci boşlukta "the" ile üstünlük anlatıldığı için süperlatif gerekir → "the most difficult".$t9c$, $t9d$"__________ you practice your pronunciation, __________ you will sound to native speakers." Bu kalıp iki şeyin birlikte değiştiğini anlatan "the + comparative..., the + comparative..." yapısıdır → doğru cevap "The more ... the more natural" (ya da benzer bir çift karşılaştırma) olmalıdır; sıfatları çıplak haliyle ("More you practice") kullanmak bu kalıpta yanlıştır, başına mutlaka "the" gelmelidir.$t9d$]),
  ('most-most-of', $t10a$most mu, most of mu? Belirleyici Testi$t10a$, $t10b$"most" ÇIPLAK bir çoğul/sayılamayan isimden önce gelirse genel bir çoğunluğu anlatır: "Most students enjoy holidays" (öğrencilerin çoğu, genel olarak). "most of" ise ardından MUTLAKA the/this/that/these/those/my/his gibi bir belirleyici veya bir zamir (us/them/you) gelir ve BELİRLİ, tanımlanmış bir grubun çoğunluğunu anlatır: "Most of the students in this class..." (bu sınıftaki öğrencilerin çoğu). YDS'nin en sık kullandığı tuzak: "most the students" gibi "most" ile isim arasında "the" olup "of" olmayan bir yapı — bu KESİNLİKLE yanlıştır, "the" her zaman "of"tan sonra gelir. Bir şıkta "most" yazıp hemen ardından "the/this/my" geliyorsa o şık elenir; doğrusu ya "most" + çıplak isim ya da "most of" + belirleyici + isimdir.$t10b$, ARRAY[$t10c$"__________ people in this country speak at least two languages." Boşluktan sonra çıplak bir çoğul isim ("people") geliyor, belirleyici yok → doğru cevap "Most"tur; "Most of" burada yanlıştır çünkü ardından "the/these" gibi bir belirleyici gelmemiştir.$t10c$, $t10d$"__________ the employees at this company have been working here for over five years." Boşluktan sonra "the employees" (belirleyici + isim) geldiği için doğru cevap "Most of"tur; sadece "Most" kullanmak için "the" kelimesinin cümleden çıkarılması gerekirdi.$t10d$]),
  ('quantifiers-much-many-few-little', $t11a$Sayılabilir mi, Sayılamaz mı? much/many/little/few Testi$t11a$, $t11b$Boşluktan hemen sonraki ismin sayılabilir çoğul mu yoksa sayılamayan tekil mi olduğuna bak: sayılamayan isimlerle (information, advice, money, traffic, furniture gibi tekil ve çoğul eki ALMAYAN isimler) much ve little kullanılır; sayılabilir çoğul isimlerle (students, cars, problems gibi -s'li isimler) many ve few kullanılır. "a lot of" / "lots of" ise HER İKİSİYLE de sorunsuz kullanılabildiği için şıklarda güvenli bir seçenek gibi görünse de, soru genellikle much/many/little/few arasındaki ayrımı test eder. İkinci kritik ayrım: "a few/a little" olumlu bir anlam taşır ("birkaç tane var, yeterli"), "few/little" (a'sız) ise olumsuz bir anlam taşır ("çok az, neredeyse yok") — bu ikisi zıt anlamlıdır ve YDS'de anlam bütünlüğü sorularında sıkça tuzak kurulur.$t11b$, ARRAY[$t11c$"How __________ time do we have before the meeting starts?" "time" sayılamayan bir isim olduğu için doğru cevap "much"tır; "many" sadece sayılabilir çoğul isimlerle ("How many minutes...") kullanılabilirdi.$t11c$, $t11d$"She has __________ friends here, so she rarely feels lonely." Burada olumlu bir anlam (yalnız hissetmiyor, demek ki yeterince arkadaşı var) olduğu için doğru cevap "a few"dür; eğer "a" olmadan sadece "few" kullanılsaydı anlam "neredeyse hiç arkadaşı yok" olur ve cümlenin devamıyla ("rarely feels lonely") çelişirdi.$t11d$]),
  ('phrasal-verbs-in-out', $t12a$in / out Parçacıklarını Anlam Grubuna Göre Çözmek$t12a$, $t12b$"in" parçacığı taşıyan phrasal verb'ler genellikle KATILMA, DAHİL OLMA veya TESLİM ETME anlamı taşır: "hand in" (teslim etmek), "join in" (katılmak), "check in" (giriş yapmak), "fit in" (uyum sağlamak). "out" parçacığı taşıyanlar ise genellikle TÜKENME, SONA ERME veya BİR BİLGİYİ ORTAYA ÇIKARMA anlamı taşır: "run out of" (tükenmek), "find out" (öğrenmek/keşfetmek), "figure out" (çözmek), "hand out" (dağıtmak). Dikkat: aynı fiil farklı parçacıkla TAMAMEN farklı anlama gelir — "hand in" (teslim etmek) ile "hand out" (dağıtmak) zıt yönde hareketi ifade eder, bu yüzden cümledeki hareketin YÖNÜNE (içeri doğru mu, dışarı/ortaya doğru mu) bakmak doğru parçacığı seçmenin anahtarıdır.$t12b$, ARRAY[$t12c$"Please __________ your assignments by Friday; late submissions will not be accepted." Ödevlerin öğretmene TESLİM EDİLMESİ (içeri doğru bir teslim hareketi) anlatıldığı için doğru cevap "hand in"dir; "hand out" (dağıtmak) burada öğretmenin öğrencilere bir şey verdiği ters yönü ifade ettiği için yanlıştır.$t12c$, $t12d$"Scientists are trying to __________ what caused the sudden drop in the fish population." Burada bilinmeyen bir nedenin ARAŞTIRILIP ORTAYA ÇIKARILMASI anlatıldığı için doğru cevap "find out"tur; "in" parçacığı burada anlamsal olarak uymaz çünkü cümle bir şeyin içine girmeyi değil, gizli bir bilginin dışarı çıkmasını anlatır.$t12d$]),
  ('phrasal-verbs-on-off', $t13a$on / off Parçacıklarını Anlam Grubuna Göre Çözmek$t13a$, $t13b$"on" parçacığı taşıyan phrasal verb'ler genellikle DEVAM ETME veya BİR CİHAZI/SİSTEMİ ÇALIŞTIRMA anlamı taşır: "go on" (devam etmek), "carry on" (sürdürmek), "turn on" (açmak), "put on" (giymek/takmak, üzerine koymak). "off" parçacığı taşıyanlar ise genellikle DURDURMA, İPTAL ETME veya AYRILMA anlamı taşır: "turn off" (kapatmak), "call off" (iptal etmek), "take off" (çıkarmak/kalkış yapmak), "set off" (yola çıkmak). Dikkat: "turn on/off" çifti doğrudan zıt anlamlıdır (açmak/kapatmak), bu yüzden bir cihazla ilgili cümlede eylemin başlatma mı durdurma mı olduğuna bakılmalı; ayrıca "off" bazen olumsuz bir sonucu ("call off" = iptal, kötü haber) işaret ederken "on" genellikle sürekliliği/olumlu devamı işaret eder.$t13b$, ARRAY[$t13c$"Due to the heavy storm, the organizers decided to __________ the outdoor concert." Fırtına nedeniyle etkinliğin İPTAL EDİLMESİ anlatıldığı için doğru cevap "call off"tur; "call on" (birine rica etmek/ziyaret etmek) burada anlamsal olarak uymaz.$t13c$, $t13d$"Despite the technical problems, the committee decided to __________ with the meeting as planned." Teknik sorunlara rağmen toplantının DEVAM ETMESİ anlatıldığı için doğru cevap "go on" ya da "carry on"dur; "go off" (patlamak, bozulmak, çalmak gibi farklı bir anlam taşır) burada cümledeki devam etme fikriyle çelişir.$t13d$]),
  ('phrasal-verbs-up-down', $t14a$up / down Parçacıklarını Anlam Grubuna Göre Çözmek$t14a$, $t14b$"up" parçacığı taşıyan phrasal verb'ler genellikle ARTIŞ, TAMAMLANMA veya ORTAYA ÇIKMA anlamı taşır: "pick up" (toplamak, artırmak), "show up" (ortaya çıkmak, gelmek), "end up" (sonunda bir duruma gelmek), "give up" (vazgeçmek — burada "up" tamamlanma/bitirme anlamı taşır). "down" parçacığı taşıyanlar ise genellikle AZALMA, DURMA veya KAYDETME anlamı taşır: "slow down" (yavaşlamak), "break down" (bozulmak, arızalanmak), "write down" (not almak, kaydetmek), "let down" (hayal kırıklığına uğratmak). Dikkat: "break down" ile "break up" birbirine çok benzer görünür ama "break down" genellikle bir CİHAZIN/SİSTEMİN veya RESMİ GÖRÜŞMENİN çökmesi için, "break up" ise bir İLİŞKİNİN/GRUBUN dağılması için kullanılır — bağlamdaki ÖZNEYE bakmak doğru parçacığı seçmenin anahtarıdır.$t14b$, ARRAY[$t14c$"After waiting for an hour, we realized he wasn't going to __________, so we left without him." Beklenen kişinin gelmemesi/ortaya çıkmaması anlatıldığı için doğru cevap "show up"tır; "show off" (hava atmak, caka satmak) burada anlamsal olarak hiç uymaz.$t14c$, $t14d$"The old printer kept __________ every few minutes, so we had to call a technician." Eski yazıcının sürekli ARIZALANMASI anlatıldığı için doğru cevap "breaking down"dır; "breaking up" burada bir cihaz için değil, genellikle bir ilişkinin/grubun dağılması için kullanıldığından bağlama uymaz.$t14d$]),
  ('present-perfect-continuous', $t15a$have been + -ing: Süreklilik ve Etkisi Süren Eylem$t15a$, $t15b$Present Perfect Continuous (have/has been + fiil-ing), geçmişte başlayıp HÂLÂ SÜRMEKTE olan bir eylemi veya yakın zamanda bitmiş olsa bile ETKİSİ/SONUCU hâlâ görünür olan bir eylemi anlatır — cümlede genellikle "for", "since", "all day", "recently", "lately" gibi süre/yakın zaman belirteçleri bulunur. YDS'nin sık kullandığı ayrım noktası şudur: cümlede eylemin SÜRESİ veya DEVAMLILIĞI vurgulanıyorsa ("How long...", "for two hours") present perfect continuous tercih edilir; eylemin SONUCU/TAMAMLANMIŞLIĞI vurgulanıyorsa (örneğin belirli bir SAYIYLA, "three times", "five reports") present perfect simple tercih edilir — devam eden bir eylemin kaç kez/kaç tane tamamlandığı sayılamaz. Ayrıca bu yapı genellikle görünür bir KANIT/BELİRTİ ile birlikte kullanılır: "Your eyes are red — have you been crying?" gibi, konuşan kişi gördüğü bir ipucundan yola çıkarak bir çıkarım yapar.$t15b$, ARRAY[$t15c$"I __________ (wait) for the bus for over 40 minutes, and it still hasn't arrived." "for over 40 minutes" ile süregelen bir eylem ve bu eylemin hâlâ devam ettiği ("still hasn't arrived") anlatıldığı için doğru cevap "have been waiting"tir; "have waited" kullanmak süreklilik/sabırsızlık vurgusunu zayıflatırdı.$t15c$, $t15d$"Look at this mess — __________ (you/cook) all afternoon?" Mutfaktaki dağınıklık (görünür bir KANIT) bir eylemin yakın zamanda SÜRDÜRÜLDÜĞÜNE işaret ettiği için doğru cevap "have you been cooking"tir; "have you cooked" sorusu daha çok "yemeği bitirdin mi" anlamına gelir ve mevcut dağınıklığın NEDENİNİ değil SONUCUNU sorar.$t15d$]),
  ('present-perfect-simple-vs-continuous', $t16a$Sonuç mu, Süreç mi? Present Perfect Simple/Continuous Ayrımı$t16a$, $t16b$Present Perfect Simple (have/has + V3) bir eylemin TAMAMLANDIĞINI ve SONUCUNU vurgular — genellikle bir SAYI, miktar veya net bir başarı/sonuç içerir: "I have written three reports this week" (kaç tane tamamlandığı önemli). Present Perfect Continuous (have/has been + -ing) ise eylemin SÜRESİNİ ve DEVAMLILIĞINI vurgular, eylem henüz BİTMEMİŞ olabilir veya bitmiş olsa bile kaç kez/kaç tane yapıldığı önemli DEĞİLDİR, sadece ne kadar SÜRDÜĞÜ önemlidir: "I have been writing reports all week" (ne kadar süredir uğraştığı önemli). Altın kural: cümlede bir SAYI/miktar şıkkı belirleyen unsur olarak geçiyorsa ("how many", "three times") simple form zorunludur; "how long", "for/since" ile süre soruluyor veya vurgulanıyorsa continuous form tercih edilir. Ayrıca kalıcı/sürekli durum bildiren fiiller (know, believe, own, belong) ASLA continuous formda kullanılmaz, her zaman simple kalır.$t16b$, ARRAY[$t16c$"She __________ (write) five articles for this magazine so far." "five articles" ile SAYILABİLİR, tamamlanmış bir sonuç belirtildiği için doğru cevap "has written"tir; "has been writing" kullanmak isteseydik cümlede bir sayı değil bir süre belirteci ("for two years") olması gerekirdi.$t16c$, $t16d$"My hands are covered in paint because I __________ (paint) the fence since this morning." Ellerin boyalı olması (kanıt) ve "since this morning" ile süregelen bir eylem anlatıldığı için doğru cevap "have been painting"tir; "have painted" kullanmak eylemin TAMAMLANDIĞINI ima eder ki bu da ellerin hâlâ boyalı olma durumuyla daha az uyumludur.$t16d$]),
  ('verb-ing-infinitive-meaning-change', $t17a$remember/stop/try + -ing veya to-infinitive: Anlam Tuzağı$t17a$, $t17b$Bazı fiillerden sonra -ing mi yoksa to-infinitive mi geldiği cümlenin anlamını TAMAMEN değiştirir, bu yüzden bu fiilleri gördüğünde otomatik bir kural uygulamak yerine ANLAMA bakılmalıdır. "remember + -ing" geçmişte yapılmış bir eylemi HATIRLAMAYI anlatır ("I remember locking the door" = kilitlediğimi hatırlıyorum, kilitledim), "remember + to-infinitive" ise yapılması GEREKEN bir görevi UNUTMAMAYI anlatır ("I remembered to lock the door" = kilitlemeyi unutmadım, kilitledim — görev henüz yapılmamışken hatırlandı). "stop + -ing" bir eylemi DURDURMAYI anlatır ("He stopped smoking" = sigarayı bıraktı), "stop + to-infinitive" ise BAŞKA bir eylemi yapmak için DURMAYI anlatır ("He stopped to smoke" = sigara içmek için durdu). "try + -ing" bir şeyi DENEME/TEST ETME anlamı taşır ("Try restarting the computer" = bir çözüm olarak yeniden başlatmayı dene), "try + to-infinitive" ise bir şeyi BAŞARMAYA ÇALIŞMA/ÇABA anlamı taşır ("I tried to open the door" = açmaya çalıştım, muhtemelen başaramadım).$t17b$, ARRAY[$t17c$"On his way to the office, he __________ (stop/buy) a coffee." Yolda durup kahve ALMAK bir AMAÇ belirttiği için doğru cevap "stopped to buy"dır; "stopped buying" kullanılsaydı anlam "kahve almayı bırakmak/kesmek" gibi tamamen farklı bir şeye dönüşürdü.$t17c$, $t17d$"I'll never forget that day — I clearly __________ (remember/see) him at the airport." Geçmişte yaşanmış bir anıyı HATIRLAMA anlatıldığı için doğru cevap "remember seeing"dir; "remember to see" kullanılsaydı bu, henüz gerçekleşmemiş, yapılması gereken bir görevi unutmama anlamına gelirdi ki bu da "that day"i hatırlamakla çelişirdi.$t17d$]),
  ('reporting-passive', $t18a$it is said that... / be said to: Kaynaksız Aktarım Kalıbı$t18a$, $t18b$Bir bilginin veya görüşün KAYNAĞINI belirtmeden, genel bir inanış/söylenti olarak aktarmak için iki eşdeğer yapı kullanılır: (1) "It + be + said/believed/thought/reported/known + that + özne + yüklem" ("It is believed that the company will expand soon") ve (2) "Özne + be + said/believed/thought + to + fiil" ("The company is believed to expand soon"). Bu iki yapı arasında ZAMAN uyumuna dikkat edilmelidir: ana cümledeki bildirme fiiliyle AYNI ANDA olan bir eylem için "to + yalın fiil" ("is believed to be"), ana cümledeki bildirme fiilinden ÖNCE gerçekleşmiş bir eylem için "to have + V3" ("is believed to have been") kullanılır — bu geçmişe atıf yapısını atlamak YDS'nin sık kurduğu bir tuzaktır. Ayrıca "it" yapısındaki "that" asla atılamaz ve "to" yapısındaki özne, "that" yapısındaki "that"tan sonraki özneyle AYNI olmalıdır.$t18b$, ARRAY[$t18c$"__________ that the ancient bridge was built over two thousand years ago." Kaynağı belirtilmeyen genel bir inanışın "it" yapısıyla aktarılması gerektiği için doğru cevap "It is believed"tir; "that" bağlacı bu yapıda asla atılamaz.$t18c$, $t18d$"The missing hikers __________ (believe/be) lost somewhere in the mountains for three days now." Kaybolma eyleminin, bildirme anından ("şu an inanılıyor") ÖNCE gerçekleşmiş ve hâlâ süren bir durum olduğu için doğru cevap "are believed to have been"dir; sadece "are believed to be" kullanmak, kaybolmanın şu anda gerçekleştiği gibi yanlış bir zaman ilişkisi kurardı.$t18d$]),
  ('countable-uncountable-nouns', $t19a$a/an Çıktı mı Çıkmadı mı? Sayılabilirlik Testi$t19a$, $t19b$Bir ismin sayılabilir mi sayılamaz mı olduğunu anlamanın en hızlı yolu şudur: isim ÇOĞUL eki (-s) alabiliyor ve "a/an" ile kullanılabiliyorsa sayılabilirdir (a book → books); isim tekil kalıyor, "a/an" ALAMIYOR ve "much/little/a bit of" ile eşleşiyorsa sayılamazdır (information, advice, furniture, news, luggage gibi — bu kelimeler Türkçede çoğul/sayılabilir gibi hissettirse de İngilizcede SAYILAMAZDIR, bu YDS'nin klasik tuzağıdır). Sayılamayan bir isimle "a/an" kullanmak veya çoğul yapmak ("an information", "informations") her zaman YANLIŞTIR; bunun yerine "a piece of information", "a bit of advice" gibi bölücü (partitive) ifadeler kullanılır. Ayrıca bazı kelimeler bağlama göre HEM sayılabilir HEM sayılamaz kullanılabilir ve anlamı değişir: "paper" (sayılamaz: kağıt maddesi / sayılabilir: a paper = makale, gazete).$t19b$, ARRAY[$t19c$"Could you give me __________ about how to fix this printer?" "advice" sayılamayan bir isim olduğu için "a/an" ile kullanılamaz, doğru cevap "some advice" ya da "a piece of advice"tir; "an advice" veya "advices" gibi şıklar her zaman yanlıştır.$t19c$, $t19d$"The professor published several __________ on climate change last year." Burada "paper" SAYILABİLİR bir anlamda (makale) kullanıldığı için çoğul eki alabilir ve doğru cevap "papers"tır; cümle kağıt maddesinden bahsetseydi ("We need more __________ for the printer") doğru cevap sayılamaz haliyle tekil "paper" olurdu.$t19d$]),
  ('adjective-preposition-ing', $t20a$Sıfat + Edattan Sonra Mutlaka -ing$t20a$, $t20b$interested in, afraid of, good at, bad at, capable of, famous for, responsible for, tired of, keen on, fond of gibi sabit sıfat+edat kalıplarından sonra bir fiil geliyorsa bu fiil MUTLAKA -ing (gerund) formunda olur, asla bare infinitive veya "to + fiil" gelmez — çünkü edattan sonra fiil her zaman -ing alır. En sık düşülen tuzak "accustomed to", "committed to", "dedicated to", "used to" (alışkanlık anlamındaki, modal "would" gibi davranan "used to + V1" ile KARIŞTIRILMAMALI) kalıplarıdır: buradaki "to" bir edattır, infinitive belirteci değildir, bu yüzden "accustomed to work" değil "accustomed to working" doğrudur. Bir şıkta sıfat+edattan hemen sonra "to + yalın fiil" görürsen bu şık büyük ihtimalle yanlıştır.$t20b$, ARRAY[$t20c$"She is capable ___ (solve) even the most complicated equations." Boşluktan önce "capable of" sabit kalıbı var, edattan ("of") sonra fiil -ing alır → doğru cevap "of solving"dir; "to solve" tuzaktır çünkü "capable" edatla değil doğrudan to-infinitive ile asla kullanılmaz.$t20c$, $t20d$"After years of driving an automatic car, he is now accustomed to ___ (drive) a manual one." Burada "to" infinitive belirteci değil edattır ("accustomed TO something"), bu yüzden doğru cevap "driving"dir; "drive" seçeneği öğrencileri "used to drive" (eskiden yapardı) kalıbıyla karıştırmak için konan klasik bir tuzaktır — "accustomed to" ile "used to V1" tamamen farklı yapılardır.$t20d$]),
  ('adverbs-of-degree', $t21a$so / such / enough / too Konum Testi$t21a$, $t21b$Boşluktan hemen sonra geleni kontrol et: çıplak bir sıfat veya zarf geliyorsa (isim YOK) "so" kullanılır ("so difficult"); bir isim öbeği geliyorsa (sıfatlı ya da sıfatsız) "such" kullanılır ("such a difficult exam", "such news"). "enough" bir sıfat/zarftan SONRA gelir ("good enough") ama bir isimden ÖNCE gelir ("enough time") — "enough good" ya da "time enough" gibi ters sıralamalar her zaman yanlıştır. "too" ise sıfat/zarftan ÖNCE gelir ve genellikle ardından "to + fiil" ile olumsuz bir sonucu belirtir ("too difficult to solve"); "so...that" ve "such...that" yapılarının aksine "too" tek başına tam bir "that" cümleciği istemez.$t21b$, ARRAY[$t21c$"It was __________ complicated problem that nobody in the class could solve it." Boşluktan sonra bir isim öbeği ("complicated problem") geldiği için doğru cevap "such a"dır; "so" burada yanlıştır çünkü "so" çıplak bir sıfat/zarftan önce kullanılır, isim öbeğinden önce değil.$t21c$, $t21d$"He didn't have __________ experience to apply for the senior position." Boşluktan sonra bir isim ("experience") var ve bir yetersizlik anlatılıyor → doğru cevap "enough"tur ("enough experience", isimden önce); "experience enough" şeklindeki ters sıralama İngilizce'de kabul edilmez.$t21d$]),
  ('so-that-such-that', $t22a$so...that / such...that Sonuç Cümlesi Testi$t22a$, $t22b$Boşluktan hemen sonraki kelimeye bak: çıplak bir sıfat veya zarf geliyorsa (araya isim girmiyorsa) "so" kullanılır ("so exhausting that"); bir isim öbeği geliyorsa (a/an + sıfat + isim, ya da sadece isim) "such" kullanılır ("such an exhausting day that", "such news that"). Tek istisna: "many/much/few/little" gibi miktar belirteçleriyle birlikte bir çoğul/sayılamayan isim geldiğinde de "so" kullanılır ("so many people that..."), çünkü bunlar gramatik olarak sıfat gibi davranır. Her iki yapı da "that" ile devam eden tam bir sonuç cümleciği gerektirir — "that" düşerse yapı sadece "so/such" vurgusu olur, sonuç anlamı taşımaz.$t22b$, ARRAY[$t22c$"The lecture was __________ boring that half the students fell asleep." Boşluktan sonra çıplak bir sıfat ("boring") var, araya isim girmiyor → doğru cevap "so"dur; "such" burada yanlıştır çünkü ardından bir isim öbeği gelmiyor.$t22c$, $t22d$"It was __________ a persuasive speech that the whole audience stood up and applauded." Boşluktan sonra isim öbeği ("a persuasive speech") geldiği için doğru cevap "such"tur; "so" seçilseydi cümlenin "so persuasive a speech that" şeklinde (sıfat isimden önce, a/an'den sonra) yeniden kurulması gerekirdi — sade "so a persuasive speech" yanlıştır.$t22d$]),
  ('time-clauses-future-meaning', $t23a$Zaman Cümleciklerinde 'will' Tuzağı$t23a$, $t23b$when, while, before, after, until, as soon as, by the time gibi bağlaçlarla kurulan ZAMAN cümleciklerinde, anlatılan olay gelecekte gerçekleşecek olsa BİLE "will" KULLANILMAZ — bunun yerine Present Simple (olay tek seferlik/eşzamanlı ise) veya Present Perfect (zaman cümleciğindeki eylem ana cümledeki eylemden ÖNCE tamamlanmış olacaksa, özellikle "by the time" ve "after" ile) kullanılır. "Will" sadece ANA cümlede (zaman cümleciği olmayan kısımda) kullanılabilir. Bir şıkta zaman bağlacından hemen sonra "will" görürsen bu şık YDS'de neredeyse her zaman yanlıştır.$t23b$, ARRAY[$t23c$"By the time she __________ (arrive) at the airport, the plane will have already taken off." "By the time" ile kurulan zaman cümleciğinde "will" kullanılmaz, Present Simple yeterlidir → doğru cevap "arrives"tir; "will arrive" tuzaktır.$t23c$, $t23d$"I will call you as soon as I __________ (finish) the meeting." Burada ana cümlede zaten "will" var ("I will call"), ama "as soon as" ile başlayan zaman cümleciğinde yine "will" kullanılamaz → doğru cevap "finish"tir, "will finish" değil — iki "will" bir cümlede zaman cümleciğiyle asla bir arada bulunmaz.$t23d$]),
  ('prepositions-time', $t24a$Zaman Edatlarını Nokta-Gün-Dönem Üçlüsüyle Ayırmak$t24a$, $t24b$Zaman ifadesinin "büyüklüğüne" göre üç kategoriye ayır: NOKTASAL anlar (saatler, öğlen/gece gibi belirli anlar, "at the weekend" İngiliz İngilizcesinde) → "at"; GÜNLER ve TARİHLER (belirli bir gün, tarih, "on Monday", "on the 5th of May", "on my birthday") → "on"; daha UZUN DÖNEMLER (aylar, yıllar, mevsimler, yüzyıllar, "in the morning") → "in". Şıklarda genellikle bir tarih/gün ifadesiyle "in" ya da bir ay/yıl ifadesiyle "on" eşleştirilerek tuzak kurulur — ifadenin tam olarak nokta mı, gün mü, yoksa daha geniş bir dönem mi olduğuna bakmak eleme için yeterlidir.$t24b$, ARRAY[$t24c$"The conference will take place __________ the 14th of March." Burada belirli bir TARİH var → doğru cevap "on"dur; "in" tuzaktır çünkü "in" daha geniş dönemler (ay, yıl) için kullanılır, belirli bir güne/tarihe değil.$t24c$, $t24d$"Most students feel more energetic __________ the morning than __________ night." İlk boşlukta geniş bir gün dönemi ("the morning") var → "in"; ikinci boşlukta noktasal bir an ("night") var → "at" — aynı cümlede iki farklı edatın doğru olmasının sebebi ifadenin kategorisinin değişmesidir.$t24d$]),
  ('adjective-order-formation', $t25a$-ing/-ed Sıfat Seçimi ve Sıralama Testi$t25a$, $t25b$-ing sıfatı bir şeyin/durumun KENDİ ÖZELLİĞİNİ anlatır ("the movie was boring" = film kendisi sıkıcı), -ed sıfatı ise o durumdan ETKİLENEN KİŞİNİN duygusunu anlatır ("I was bored" = ben sıkıldım). Özne bir İNSAN ve bir duygudan bahsediliyorsa çoğunlukla -ed, özne bir ŞEY/DURUM/"it" ise çoğunlukla -ing doğru olur. Birden fazla sıfat art arda sıralanırken İngilizce'de genel sıra şudur: görüş/yorum (beautiful) → boyut (small) → yaş (old) → şekil → renk → köken (Italian) → malzeme (wooden) → amaç; bu sıranın tersine çevrildiği bir şık YDS'de doğal/doğru kabul edilmez.$t25b$, ARRAY[$t25c$"The documentary about climate change was so __________ that nobody in the room could look away." Özne "the documentary" (bir şey, duyguyu yaratan kaynak) olduğu için doğru cevap "fascinating"tir; "fascinated" yanlıştır çünkü belgesel bir duygu hissetmez, duyguyu yaratan odur.$t25c$, $t25d$"__________ round antique wooden table stood in the corner of the room." Doğru sıfat sırası görüş/boyut değil ama burada şekil-yaş-malzeme sırasıyla "A beautiful round antique wooden table" gibi bir dizilim doğrudur; sıfatların yerini değiştirip "A wooden antique round table" demek İngilizce'de doğal kabul edilmeyen bir sıralamadır.$t25d$]),
  ('adjectives-ending-in-ly', $t26a$-ly ile Biten ama Aslında Sıfat Olan Kelimeler$t26a$, $t26b$-ly eki genellikle bir sıfatı zarfa çevirir (quick → quickly), AMA friendly, lovely, lonely, silly, elderly, likely, costly, daily, deadly, cowardly, timely gibi kelimeler -ly ile bitmesine RAĞMEN kendileri zaten birer SIFATTIR — bunların "-lyly" şeklinde ayrı bir zarf hali YOKTUR. Bu kelimeler bir fiili değil bir İSMİ niteler veya "be" fiilinden sonra kullanılır ("a friendly dog", "She is lovely"). Bir cümlede bu kelimelerden biri bir FİİLİ nitelemek için kullanılmaya çalışılıyorsa (zarf konumunda), bu yanlıştır — doğru yol "in a friendly way/manner" gibi bir çevre ifade kullanmaktır.$t26b$, ARRAY[$t26c$"The new neighbor greeted everyone __________." Burada "greeted" fiilini nitelemek için bir zarf gerekir, ama "friendly" bir sıfattır, zarf değil → doğru cevap "in a friendly way/manner"dir; sadece "friendly" kullanmak yanlıştır çünkü "friendlily" diye bir kelime yoktur.$t26c$, $t26d$"My grandmother is a __________ old woman who always has a story to tell." Burada bir İSMİ ("woman") niteleyen bir sıfat gerekiyor ve "lovely" tam olarak bu konumda doğru kullanılan bir sıfattır — öğrenciler -ly ekine bakıp bunu yanlışlıkla bir zarf sanıp elediğinde hata yapar.$t26d$]),
  ('all-both-neither-either', $t27a$all / both / neither / either Sayı Testi$t27a$, $t27b$Önce kaç şeyden bahsedildiğine bak: TAM OLARAK İKİ şey/kişi söz konusuysa "both" (ikisi de, olumlu), "either" (ikisinden biri, genelde soru/olumsuzlukla birlikte "not...either") veya "neither" (ikisinden hiçbiri, kendi içinde olumsuzluk taşır, ayrıca "not" eklenmez) kullanılır; İKİDEN FAZLA şey söz konusuysa "all" kullanılır. "of" ile kullanıldıklarında (both of, either of, neither of, all of) ardından belirli bir isim grubu (the, these, my gibi belirteçli) veya zamir gelir. Özne-yüklem uyumunda "neither/either + tekil isim" tekil fiil alır ("Neither answer is correct"), "both/all + çoğul isim" çoğul fiil alır.$t27b$, ARRAY[$t27c$"__________ of the three candidates performed exceptionally well in the interview." Üç adaydan bahsedildiği (ikiden fazla) için doğru cevap "All"dur; "both" burada yanlıştır çünkü "both" sadece tam olarak iki şey için kullanılabilir.$t27c$, $t27d$"__________ of the two methods works efficiently, so you can choose whichever you prefer." İki yöntemden bahsediliyor ve ikisinin de işe yaradığı olumlu bir şekilde anlatılıyor → doğru cevap "Both"tur (çoğul fiil "work" de kullanılabilir); "Neither" burada yanlıştır çünkü "neither" olumsuz bir anlam taşır (hiçbiri işe yaramaz demektir), cümledeki anlamla çelişir.$t27d$]),
  ('already-yet-still', $t28a$already / yet / still Konum ve Anlam Testi$t28a$, $t28b$already OLUMLU cümlelerde, beklenenden önce ya da şu ana kadar gerçekleşmiş bir şeyi vurgular ve genelde yardımcı fiille ana fiil ARASINA ("has already finished") ya da cümle sonuna yerleşir; yet genellikle OLUMSUZ ve SORU cümlelerinde "henüz" anlamıyla cümle SONUNDA kullanılır ("Haven't you finished yet?"); still devam etmekte olan bir durumu vurgular ve HER ZAMAN yardımcı fiilden/ana fiilden ÖNCE gelir ("is still waiting", "still haven't received") — "still" cümle sonunda KULLANILMAZ, bu YDS'nin sevdiği bir tuzaktır. Bir şıkta "still" cümle sonunda görülürse o şık kesinlikle yanlıştır.$t28b$, ARRAY[$t28c$"Have you received a reply from the university __________?" Soru cümlesi ve "henüz" anlamı aranıyor, kelime cümle sonunda → doğru cevap "yet"tir; "already" bu konumda ve bu bağlamda doğal değildir çünkü "already" tipik olarak olumlu/beklenti bildiren cümlelerde kullanılır.$t28c$, $t28d$"We __________ haven't heard back from the embassy about our visa application." Devam eden, bitmemiş bir durum (hâlâ cevap yok) ve kelime yardımcı fiilden ÖNCE konumlanmış → doğru cevap "still"dir; "yet" bu konumda (cümle başında/ortasında, cümle sonunda değil) kullanılamaz, "yet" cümle sonuna yerleşmelidir.$t28d$]),
  ('as-as-comparison', $t29a$as...as Eşitlik Yapısında Üstünlük Eki Tuzağı$t29a$, $t29b$as...as yapısı iki şeyin EŞİT derecede olduğunu anlatır ve araya giren sıfat/zarf her zaman YALIN (orijinal) halde kalır, ASLA "-er" üstünlük eki almaz — "as taller as" gibi bir yapı İngilizce'de yoktur, doğrusu "as tall as"tır. Olumsuz eşitsizlik için "not as...as" veya (daha resmi) "not so...as" kullanılır. Karşılaştırılan iki öğe de aynı gramatik yapıda (paralel) olmalıdır: bir isimle bir isim, bir cümlecikle bir cümlecik karşılaştırılmalıdır. Bir şıkta "as" ile "-er" ekli bir sıfat/zarf bir arada görülürse bu şık kesinlikle yanlıştır.$t29b$, ARRAY[$t29c$"This smartphone is not __________ the previous model in terms of battery life." Olumsuz bir eşitlik/karşılaştırma kuruluyor → doğru cevap "as good as" (ya da "as reliable as") gibi yalın bir sıfatla "as...as" yapısıdır; "as better as" seçeneği kesinlikle yanlıştır çünkü "as...as" içinde üstünlük eki ("-er") asla kullanılmaz.$t29c$, $t29d$"She finished the marathon __________ her older brother did last year." İki ayrı olayın (kendisinin ve kardeşinin koşusu) eşit derecede hızlı/iyi olduğu anlatılıyor, karşılaştırılan iki taraf da cümlecik yapısında → doğru cevap "as quickly as"tır; "as quicker as" gibi bir seçenek yine aynı üstünlük-eki tuzağı yüzünden yanlıştır.$t29d$]),
  ('be-about-to', $t30a$be about to: 'Tam O Anda' Sinyalini Yakalamak$t30a$, $t30b$"be about to" + yalın fiil, konuşma anından hemen sonra, neredeyse o anda gerçekleşecek bir eylemi anlatır — "going to"dan (daha uzak, planlanmış bir niyet) ve "will"den (anlık karar/genel tahmin) farkı, kesin bir ÂNİLİK vurgusudur ve sıklıkla "just" ile pekiştirilir ("just about to"). Geçmiş zamanda "was/were about to + fiil" kalıbı, gerçekleşmek ÜZEREYKEN bir şey tarafından KESİNTİYE UĞRAYAN bir eylemi anlatır ve neredeyse her zaman "when + ani bir geçmiş zaman olayı" ile birlikte gelir: "I was about to leave when the phone rang." Sınavda boşluktan sonra ya da cümle içinde "next month/next year" gibi UZAK bir zaman ifadesi varsa "about to" kesinlikle elenir — bu yapı sadece ÇOK YAKIN bir anı ifade eder, uzak planlar için "going to" kullanılmalıdır.$t30b$, ARRAY[$t30c$"He ___ when his phone suddenly rang, so he sat back down and answered it." Cümlede "when" ile aniden kesintiye uğrayan, tam gerçekleşmek üzere olan bir eylem anlatılıyor → doğru cevap "was about to leave"dir; bu kalıp "was about to + V + when + ani olay" şeklinde sabitlenmiştir.$t30c$, $t30d$"She ___ finish her final exams next month, so she's already planning her summer trip." Burada "next month" ifadesi UZAK bir gelecek zamanı işaret ettiği için "about to" (çok yakın an) yanlıştır — doğru cevap, önceden planlanmış bir niyeti anlatan "is going to"dur.$t30d$]),
  ('gone-vs-been', $t31a$been to / gone to: Dönmüş mü, Hâlâ Orada mı?$t31a$, $t31b$"have been to" bir yere GİTMİŞ ve GERİ DÖNMÜŞ olmayı, yani bir deneyimi anlatır; bu yüzden genellikle "ever, never, three times" gibi deneyim belirteçleriyle birlikte görülür: "I have been to Japan three times." "have gone to" ise özne o yere gitmiş ve HÂLÂ ORADA ya da yolda olup henüz dönmemiş demektir — bu yüzden konuşan kişi ("I") için mantıksal olarak "I have gone to..." neredeyse hiç kullanılmaz (çünkü konuşuyorsa zaten dönmüştür ya da oradadır, cümleyi kurması garip olur), bu kalıp neredeyse her zaman ÜÇÜNCÜ TEKİL/ÇOĞUL şahıslarla kullanılır: "She has gone to the supermarket" (şu an orada, henüz dönmedi). Sınavda cümlede "she'll be back soon / he's not here right now" gibi KİŞİNİN HÂLÂ YOK olduğunu gösteren bir ipucu varsa "gone" doğrudur; sayı/deneyim belirteci ("three times", "ever") varsa "been" doğrudur.$t31b$, ARRAY[$t31c$"Where's Mary? She ___ to the supermarket; she'll be back in ten minutes." Cümledeki "she'll be back" ifadesi Mary'nin ŞU AN orada/yolda olduğunu, henüz dönmediğini gösteriyor → doğru cevap "has gone"dur.$t31c$, $t31d$"I ___ to Japan three times, and I loved every single trip." Burada "three times" bir deneyim sayacı ve konuşan kişi (I) şu an konuştuğuna göre zaten geri dönmüş → doğru cevap "have been"dir; "have gone" burada anlamsız olurdu.$t31d$]),
  ('compound-nouns', $t32a$Birleşik İsimlerde Çoğul Tuzağı: Hangi Kelime -s Alır?$t32a$, $t32b$İki ayrı kelimeden oluşan birleşik isimlerde (noun + noun) çoğul eki SADECE SON kelimeye eklenir, ilk kelime sıfat gibi davranır ve TEKİL kalır: "bus stop" → "bus stops" ("buses stop" DEĞİL), "swimming pool" → "swimming pools", "book shelf" → "book shelves". Bir SAYI + İSİM birleşik sıfat olarak başka bir isimden ÖNCE kullanıldığında (tire ile yazılır) ilk kelime HER ZAMAN TEKİL kalır, çoğul eki ASLA almaz: "a ten-year-old boy" (DOĞRU), "a ten-years-old boy" (YANLIŞ) — çünkü bu artık bir isim değil, sıfat öbeğidir. Tireli bileşik isimlerde ("mother-in-law", "passer-by") ise durum TERSİNE döner: çoğul eki, bileşiğin ANA isim olan İLK kısmına eklenir, çünkü gerçek isim orasıdır: "mothers-in-law", "passers-by" ("mother-in-laws" YANLIŞTIR).$t32b$, ARRAY[$t32c$"The new hotel has two ___ on its top floor, both with a view of the sea." Burada "swimming pool" bir noun+noun bileşiği olduğu için çoğul eki sadece son kelimeye eklenir → doğru cevap "swimming pools"tur; "swimmings pool" kesinlikle yanlıştır.$t32c$, $t32d$"She is the proud mother of a ___ girl who already speaks two languages." Burada sayı+isim yapısı ("four-year-old") bir sıfat öbeği olarak isimden ÖNCE kullanıldığı için tireli ve TEKİL kalmalıdır → doğru cevap "four-year-old"dur; "four-years-old" yanlıştır.$t32d$]),
  ('by-until', $t33a$by / until Farkı: Bitmiş mi, Sürüyor mu?$t33a$, $t33b$"by" bir EYLEMİN en geç ne zamana kadar TAMAMLANMIŞ olması gerektiğini belirtir ve genellikle bitiş/tamamlanma bildiren fiillerle kullanılır (finish, complete, submit, arrive, hand in): "Submit the report by Friday" = en geç Cuma'ya kadar rapor TESLİM EDİLMİŞ olmalı, Cuma'dan sonra değil. "until/till" ise bir DURUMUN ya da SÜREKLİ bir eylemin ne zamana kadar DEVAM EDECEĞİNİ anlatır ve süreklilik bildiren fiillerle kullanılır (stay, wait, work, live, remain, continue): "Wait until 5 pm" = saat 5'e kadar beklemeye DEVAM ET. Sınavda boşluktan önceki fiile bak: tek seferlik, tamamlanan bir eylem (deadline mantığı) varsa "by"; sürekli/kesintisiz devam eden bir durum varsa "until" doğrudur. Ayrıca "not...until" kalıbı, bir şeyin o ana kadar GERÇEKLEŞMEYECEĞİNİ (ancak ondan sonra olacağını) anlatır ve "not...by" ile karıştırılmamalıdır.$t33b$, ARRAY[$t33c$"Please make sure all the documents are ready ___ Monday morning at the latest." Burada "ready" olma durumu bir DEADLINE'a (en geç Pazartesi) bağlı, tamamlanmış olma hali söz konusu → doğru cevap "by"dır.$t33c$, $t33d$"The shop will remain closed ___ the renovation work is fully completed." Burada "remain closed" sürekli bir durumu anlatıyor ve bu durum bir noktaya KADAR devam edecek → doğru cevap "until"dur; "by" burada yanlış olurdu çünkü "kapalı kalma" tek seferlik tamamlanan bir eylem değildir.$t33d$]),
  ('by-with-agent-instrument', $t34a$Edilgen Çatıda Fail mi, Araç mı? by/with Ayrımı$t34a$, $t34b$Edilgen (passive) cümlelerde eylemi GERÇEKLEŞTİREN KİŞİ ya da ÖZNE "by" ile belirtilir: "The window was broken by the boy" (camı kıran: çocuk — bir FAİL). Eylemi gerçekleştirmek için kullanılan ARAÇ/ALET/MADDE ise "with" ile belirtilir: "The window was broken with a stone" (kullanılan araç: taş). İkisi aynı cümlede birlikte de bulunabilir: "The window was broken by the boy with a stone." Sınavda boşluktan sonraki kelimenin türüne bak: CANLI bir fail (bir kişi, bir hayvan, bir kurum, hatta "the storm/the wind" gibi doğa güçleri) geliyorsa "by" doğrudur; CANSIZ bir alet/madde/malzeme (a hammer, a knife, glue, paint, a special formula) geliyorsa "with" doğrudur — bu iki seçenek sınavda neredeyse her zaman birbirinin çeldiricisi olarak sunulur.$t34b$, ARRAY[$t34c$"The ancient vase was accidentally knocked over and broken ___ one of the museum visitors." Boşluktan sonra bir KİŞİ (fail) geldiği için doğru cevap "by"dır; cam kıran araç değil, bir insan olduğu için "with" burada yanlış olur.$t34c$, $t34d$"The old wooden door was sealed shut ___ a thick layer of dried paint." Boşluktan sonra CANSIZ bir madde (boya) geldiği ve bu madde kapıyı kapatmak için kullanılan ARAÇ olduğu için doğru cevap "with"tir; "by" burada yanlıştır çünkü boya bir fail değildir.$t34d$]),
  ('during-while', $t35a$during / while Farkı: İsim mi, Cümlecik mi?$t35a$, $t35b$"during" ardından her zaman bir İSİM ya da isim öbeği gelir: "during the meeting", "during the summer", "during his speech." "while" ardından ise ÖZNE + YÜKLEM içeren TAM BİR CÜMLECİK gelir: "while he was speaking", "while I was cooking." İkisi de "...sırasında/esnasında" anlamı taşısa da yapısal olarak kesinlikle birbirinin yerine geçmez — "during he was speaking" ya da "while the meeting" gibi yapılar gramer hatasıdır. Sınavda boşluktan HEMEN SONRASINA bak: tek bir isim/isim öbeği mi geliyor, yoksa özne+fiil mi? Buna göre karar ver. Ayrıca "during"i "for" ile karıştırmamaya dikkat et: "for" bir sürenin UZUNLUĞUNU verir ("for two hours"), "during" ise bir zaman DİLİMİNİN İÇİNDE gerçekleştiğini belirtir ("during the two-hour meeting").$t35b$, ARRAY[$t35c$"She fell asleep ___ the long, boring lecture on economic history." Boşluktan sonra bir isim öbeği ("the long, boring lecture") geldiği için doğru cevap "during"dir; "while" burada özne+yüklem gerektirdiği için yanlıştır.$t35c$, $t35d$"The lights suddenly went out ___ we were watching the final scene of the movie." Boşluktan sonra özne+yüklem içeren tam bir cümlecik ("we were watching...") geldiği için doğru cevap "while"dır; "during" burada bir isim öbeği gerektirdiği için yanlıştır.$t35d$]),
  ('irregular-plurals', $t36a$Düzensiz Çoğullarda Ezber Değil, Kalıp Tanıma$t36a$, $t36b$Düzensiz çoğul isimleri üç ana kalıpta grupla: (1) kök değişimi yapan eski İngilizce kökenli isimler — man→men, woman→women, child→children, foot→feet, tooth→teeth, mouse→mice, goose→geese; (2) tekili ve çoğulu AYNI olan isimler — sheep, deer, fish (genellikle), series, species, aircraft; (3) Latince/Yunanca kökenli akademik/bilimsel isimler — phenomenon→phenomena, criterion→criteria, analysis→analyses, crisis→crises, datum→data (bu grupta -on/-um ile biten tekiller -a ile, -is ile biten tekiller -es ile çoğul olur). Sınavda bu isimler genellikle ÖZNE-YÜKLEM UYUMU sorularında karşına çıkar: çoğul anlam taşıyan bir isim (criteria, phenomena, data) cümlede ÖZNE ise fiil de ÇOĞUL olmalıdır — "The criteria ARE strict" doğru, "The criteria IS strict" ya da "criterias" gibi çoğul eki fazladan eklenmiş bir şık kesinlikle yanlıştır.$t36b$, ARRAY[$t36c$"Several new ___ of butterfly were discovered in the rainforest last year." "species" hem tekil hem çoğul olarak aynı şekilde yazılan bir isimdir ve burada çoğul anlamda kullanılmıştır → doğru cevap "species"tir; "speciess" diye bir form yoktur.$t36c$, $t36d$"The ___ used to evaluate the candidates were published on the university's website." "criterion"un çoğulu "criteria"dır ve cümledeki fiil zaten çoğul ("were") olduğu için özneyle uyumlu olmalı → doğru cevap "criteria"dır; "criterias" ya da tekil "criterion" (fiille uyumsuz) burada yanlıştır.$t36d$]),
  ('each-every-difference', $t37a$each / every Ayrımı: Teker Teker mi, Toptan mı?$t37a$, $t37b$"each" bir gruptaki üyeleri TEK TEK, birey birey ele alır ve İKİ üyeli bir grupla bile kullanılabilir: "each of the two candidates." "every" ise bir grubu BÜTÜN olarak genellemek için kullanılır ve EN AZ ÜÇ üyeli bir grup gerektirir — ikili bir grupla "every" kullanılmaz. "each" isimsiz, tek başına da kullanılabilir ("Each has its own strengths") ve sıkça "each of + the/my/these" kalıbıyla görülür; "every" ise ASLA isimsiz ya da "of" ile kullanılmaz ("every of the students" KESİNLİKLE YANLIŞTIR), doğrudan tekil bir isimle birleşir ("every student"). Ayrıca "every", sıklık ifadelerinde de kullanılır ("every two hours", "every other day") — bu kullanımda "each" tercih edilmez. Sınavda boşluktan sonra "of the two..." gibi İKİLİ bir grup görürsen "every" otomatik olarak elenir.$t37b$, ARRAY[$t37c$"___ of the two finalists gave an impressive speech, but only one of them could win the prize." Burada sadece İKİ finalistten bahsediliyor ve "every" en az üç üye gerektirdiği için elenir → doğru cevap "Each"tir.$t37c$, $t37d$"___ student in the department must submit the application form by Friday, with no exceptions." Burada genel bir kural TÜM bölüm öğrencilerine (üç veya daha fazla kişiye) uygulanıyor → doğru cevap "Every"dir; "Each" de gramatik olarak mümkün olsa da "no exceptions" ifadesiyle kurulan kesin genelleme tonu "every"yi daha doğru kılar.$t37d$]),
  ('verb-preposition-ing', $t38a$Edattan Sonra Her Zaman -ing: 'to' Tuzağına Dikkat$t38a$, $t38b$Bir EDATTAN (in, on, at, about, for, of, without, before, after, by vb.) hemen sonra gelen fiil HER ZAMAN -ing (gerund) formunda olur, asla "to + yalın fiil" gelmez: "interested in learning" DOĞRU, "interested in to learn" YANLIŞ. En sık tuzak "to"nun bir EDAT olarak kullanıldığı sabit kalıplarda ortaya çıkar — "look forward to", "be used to", "object to", "in addition to", "when it comes to" gibi kalıplarda bu "to" bir infinitive belirteci DEĞİL, bir EDATTIR, bu yüzden ardından -ing gelir: "I look forward to seeing you" DOĞRU, "I look forward to see you" YANLIŞ. Sınavda boşluktan hemen ÖNCE bir edat (özellikle bu kalıplardaki "to") görürsen, şıklar arasında "to + yalın fiil" olan her seçenek otomatik olarak elenir.$t38b$, ARRAY[$t38c$"She is really looking forward ___ her family again after two years abroad." "look forward to" kalıbındaki "to" bir edattır, ardından -ing gelir → doğru cevap "to seeing"dir; "to see" burada yaygın bir hatadır ve yanlıştır.$t38c$, $t38d$"He apologized ___ late to the meeting without giving any real explanation." "apologize for" kalıbındaki "for" bir edattır ve ardından -ing gelir → doğru cevap "for being"dir; "for to be" ya da "to be" gramer olarak burada mümkün değildir.$t38d$]),
  ('verb-object-infinitive', $t39a$Fiil + Nesne + to-infinitive: Kimin Ne Yapacağını Doğru Sıralamak$t39a$, $t39b$want, tell, ask, would like, expect, allow, encourage, remind, warn gibi fiillerden sonra NESNE (eylemi gerçekleştirecek kişi) + to-infinitive kalıbı kullanılır: "I want you to help me" (yardım edecek olan: sen, ben değil) — nesne araya MUTLAKA girmelidir, "I want to help me" ya da nesnesiz "tell to come" gibi yapılar YANLIŞTIR. Dikkat edilmesi gereken önemli bir istisna: "suggest" ve "recommend" bu kalıba UYMAZ — bu iki fiilden sonra nesne+to-infinitive DEĞİL, "that" cümleciği ya da doğrudan -ing kullanılır ("suggest going", "suggest that he go"); "suggest him to go" çok yaygın yapılan ama KESİNLİKLE YANLIŞ olan bir hatadır. Sınavda "suggest/recommend" görüp hemen ardından "nesne + to-infinitive" içeren bir şık varsa, o şık otomatik olarak elenmelidir.$t39b$, ARRAY[$t39c$"The coach always encourages his players ___ hard even when the team is losing." "encourage" fiili nesne ("his players") + to-infinitive kalıbı ister → doğru cevap "to try"dir; nesnesiz "trying" ya da "try" burada yanlıştır.$t39c$, $t39d$"The doctor suggested ___ more water every day, but didn't specify an exact amount." "suggest" fiili nesne+to-infinitive kalıbına UYMADIĞI için ardından -ing gelir → doğru cevap "drinking"dir; "him to drink" gibi bir yapı burada yaygın ama yanlış bir hata olurdu.$t39d$]),
  ('for-since-how-long', $t40a$for / since Ayrımını Saniyede Çözmek$t40a$, $t40b$Boşluktan hemen sonraki ifadenin TÜRÜNE bak: bir SÜRE ifadesi (three years, two weeks, a long time, ages) geliyorsa cevap "for"dur; bir BAŞLANGIÇ NOKTASI (1998, last Monday, she graduated, childhood) geliyorsa cevap "since"tir. "Since" her zaman present perfect (have/has + V3) ile kullanılır, çünkü o noktadan bugüne kadar süren bir durumu anlatır; "for" ise present perfect, past simple veya present perfect continuous ile de gelebilir, bu yüzden tek başına zamanı belirlemez — asıl ayraç her zaman kendisinden SONRA gelen ifadenin süre mi nokta mı olduğudur. "How long" sorusu bu iki yapıyı tetikleyen klasik soru kalıbıdır ve cevapta mutlaka for/since'den biri beklenir.$t40b$, ARRAY[$t40c$"She has been working at this hospital __________ she finished medical school." Boşluktan sonra "she finished medical school" bir BAŞLANGIÇ NOKTASI (olay) olduğu için doğru cevap "since"tir; "for" gelseydi ardından "ten years" gibi bir süre ifadesi gerekirdi.$t40c$, $t40d$"They haven't seen each other __________ almost a decade." Boşluktan sonra "almost a decade" bir SÜRE ifadesi olduğu için doğru cevap "for"dur; "since" kullanılsaydı "2014" gibi bir başlangıç noktası gerekirdi, bir süre ifadesiyle asla kullanılmaz.$t40d$]),
  ('future-present-continuous', $t41a$Planlanmış Gelecek: Present Continuous Sinyalini Yakalamak$t41a$, $t41b$Bir cümlede gelecek zaman belirteci (tomorrow, next week, at 5 p.m. on Friday) VARSA ve cümle kişinin ÖNCEDEN DÜZENLEDİĞİ, takvime/plana bağlı bir eylemden bahsediyorsa (bir buluşma, bir uçuş, bir toplantı), "will" değil present continuous (am/is/are + -ing) doğru cevaptır — çünkü bu, sadece bir tahmin değil, zaten ayarlanmış somut bir düzenlemedir. Cümlede "arrange, meet, fly, leave" gibi randevu/seyahat bildiren fiiller ve kesin bir zaman/yer detayı (hangi uçakla, saat kaçta, kiminle) bir aradaysa bu, present continuous'un en güçlü işaretidir; buna karşılık cümle o anda alınan bir karar veya belirsiz bir tahminse ("I think it will rain") "will" doğru kalır.$t41b$, ARRAY[$t41c$"I can't make it to the meeting on Thursday — I __________ my parents at the airport that afternoon." Burada önceden planlanmış, saati belli bir havaalanı karşılaması anlatıldığı için doğru cevap "am meeting"tir; "will meet" o anda alınan bir karar izlenimi verir ve önceden ayarlanmış bir plana uymaz.$t41c$, $t41d$"Don't worry about the weather forecast — I'm sure it __________ fine by the weekend." Burada kesin bir düzenleme değil, konuşmacının o anki TAHMİNİ anlatıldığı için doğru cevap "will be"dir; "am being" burada hem anlamca hem yapıca yanlıştır çünkü hava durumu insanın planladığı bir şey değildir.$t41d$]),
  ('good-well-difference', $t42a$good / well: Ne Niteliyor, Ona Bak$t42a$, $t42b$Boşluktan sonra ya da önce bir İSİM varsa ve o ismin niteliğinden bahsediliyorsa ("a good book", "the food was good") cevap sıfat olan "good"tur; boşluk bir FİİLİ nitelendiriyorsa ("she sings well", "he did well on the exam") cevap zarf olan "well"dir. YDS'nin sık kullandığı tuzak, "be" fiiliyle kurulan cümlelerde ortaya çıkar: "feel, look, seem, be" gibi bağlantı (linking) fiillerinden sonra normalde sıfat beklenir, ama "well" istisnai olarak bu konumda SAĞLIK durumunu anlatan bir SIFAT olarak da kullanılabilir ("I don't feel well" = kendimi iyi hissetmiyorum, hasta gibi). Yani "well" gördüğünde önce cümlenin sağlıkla mı ilgili olduğuna, değilse hangi kelimeyi (isim mi fiil mi) nitelediğine bak.$t42b$, ARRAY[$t42c$"He performed so __________ in the final interview that they offered him the position immediately." Boşluk "performed" (fiil) eylemini nitelediği için doğru cevap zarf olan "well"dir; "good" bir fiili asla niteleyemez.$t42c$, $t42d$"My grandmother hasn't been feeling __________ lately, so she's seeing a doctor tomorrow." Burada "feel" bağlantı fiilinden sonra sağlık durumu anlatıldığı için istisnai olarak "well" (sıfat, 'iyi/sağlıklı' anlamında) doğru cevaptır; "good" burada genel bir ruh hali anlatır ama hastalık/sağlık bağlamında tercih edilen kelime "well"dir.$t42d$]),
  ('had-better-would-rather', $t43a$had better / would rather: Uyarı mı, Tercih mi?$t43a$, $t43b$Cümlede bir UYARI ya da yapılmazsa KÖTÜ BİR SONUÇ doğacağı hissi varsa (genellikle "or", "otherwise" ile devam eder) doğru yapı "had better + V1"dir ("You'd better hurry, or you'll miss the train"). Cümle iki seçenek arasında bir TERCİHİ anlatıyorsa ("X yapmak yerine Y yapmayı tercih ederim") doğru yapı "would rather + V1"dir; eğer tercih BAŞKA BİR KİŞİNİN eylemiyle ilgiliyse "would rather + özne + past simple" kullanılır ("I'd rather you left now" — şu an için bile geçmiş zaman formu kullanılır, bu YDS'nin klasik tuzağıdır). Her iki yapıdan sonra da "to" KULLANILMAZ: "had better to go" ya da "would rather to go" kesinlikle yanlıştır.$t43b$, ARRAY[$t43c$"You __________ finish the report today, or the client will cancel the contract." Cümlede açık bir UYARI ve olumsuz sonuç ("or the client will cancel") olduğu için doğru cevap "had better"dır; "would rather" burada bir tercih değil bir zorunluluk/uyarı anlatıldığı için uygun değildir.$t43c$, $t43d$"I'd rather you __________ about this to anyone else for now." Tercih BAŞKA bir kişinin (you) eylemiyle ilgili olduğu için fiil past simple formunda gelir → doğru cevap "didn't talk"tur; "don't talk" ya da "won't talk" bu yapıda kullanılmaz.$t43d$]),
  ('prepositions-of-movement', $t44a$Hareket Edatlarını Varış Noktasına Göre Seçmek$t44a$, $t44b$Bir hareket edatı seçerken cümledeki eylemin VARDIĞI YERİN TÜRÜNE bak: kapalı bir alanın İÇİNE giriş "into" ("she walked into the room"), düz bir YÜZEYİN ÜSTÜNE çıkış "onto" ("the cat jumped onto the table"), bir şeyin İÇİNDEN GEÇİŞ "through" ("they drove through the tunnel"), bir alanın YÜZEYİ BOYUNCA/KARŞIDAN KARŞIYA geçiş ise "across" ("she swam across the river") ile anlatılır. "To" sadece genel bir YÖNELİMİ/varılacak hedefi belirtir, içine girme ya da üstüne çıkma gibi bir detay vermez ("go to the park"). YDS'de bu edatlar genellikle fiilin anlamıyla (jump, walk, drive, swim, climb) birlikte test edilir — fiilin fiziksel olarak NASIL bir hareketi anlattığını gözünde canlandırmak doğru edatı bulmanın en hızlı yoludur.$t44b$, ARRAY[$t44c$"Without knocking, he suddenly burst __________ the office, startling everyone inside." Kapalı bir mekânın İÇİNE ani bir giriş anlatıldığı için doğru cevap "into"dur; "to" sadece ofise doğru gidildiğini anlatır, içeri girildiğini değil.$t44c$, $t44d$"The hikers had to wade __________ the shallow stream to reach the other side of the trail." Burada bir suyun YÜZEYİ BOYUNCA karşıya geçiş anlatıldığı için doğru cevap "across"tur; "through" kullanılsaydı suyun içinden (örneğin bir mağaradan) geçildiği izlenimi verirdi, yüzeyden geçişi değil.$t44d$]),
  ('causative-have-something-done', $t45a$Kim Yaptı? have/get something done Testi$t45a$, $t45b$Cümlede özne, bir işi KENDİSİ yapmıyor, bir BAŞKASINA YAPTIRIYORsa (berbere saç kestirmek, tamirciye araba tamir ettirmek gibi) doğru yapı "have/get + nesne + past participle (V3)"dir: "I had my hair cut" (saçımı kestirdim — kuaför kesti), "I cut my hair" (saçımı kendim kestim) ile TAMAMEN farklı bir anlam taşır. Bu yapıda nesneden sonra ASLA "to" ya da V1 gelmez — "have my car to repair" ya da "have my car repair" kesinlikle yanlıştır, sadece V3 (past participle) gelir. "Get" kullanıldığında anlam aynıdır ama biraz daha gayri resmi ve bazen işin tamamlanması için çaba gösterildiği vurgusu taşır ("I got my passport renewed just in time").$t45b$, ARRAY[$t45c$"I don't have time to fix the printer myself, so I'll __________ it __________ by the IT department tomorrow." Özne işi kendisi yapmayıp BAŞKASINA yaptırdığı için doğru yapı "have ... repaired"tir; "repair" (V1) ya da "to repair" bu kalıpta kullanılmaz.$t45c$, $t45d$"She was so busy before the wedding that she __________ her dress __________ by a professional tailor instead of sewing it herself." Yine iş başkasına yaptırıldığı için doğru cevap "had ... altered/made" (V3) yapısıdır; "altering" (-ing) ya da "alter" (V1) bu kalıpta yanlıştır.$t45d$]),
  ('if-unless-in-case', $t46a$if / unless / in case: Koşul mu, Tedbir mi?$t46a$, $t46b$"If" normal bir koşulu anlatır ("eğer X olursa Y olur"); "unless" ise "if...not" ile AYNI anlamı taşır, yani "eğer X olmazsa" demektir — bu yüzden "unless" ile kurulan bir cümlede fiili bir kez daha olumsuz yapmak ("unless he doesn't come") ÇİFT OLUMSUZLUK hatasıdır ve kesinlikle yanlıştır. "In case" ise bambaşka bir mantık taşır: gerçekleşmesi KOŞUL olan bir şeyi değil, gerçekleşme İHTİMALİNE karşı ÖNCEDEN alınan bir TEDBİRİ anlatır — "Take an umbrella in case it rains" (yağmur yağma ihtimaline karşı önlem al, yağmur yağınca şemsiyeyi kullan demek değildir, önceden yanına al demektir). Bu üçünü ayırt etmenin anahtarı, cümlenin bir KOŞULU mu yoksa bir ÖNLEMİ mi anlattığını sormaktır.$t46b$, ARRAY[$t46c$"__________ you apologize to her, she won't forgive you for what you said." Cümle "eğer özür dilemezsen" anlamını taşıdığı için doğru cevap "Unless"tir; "If" kullanılsaydı fiilin olumsuz kalması gerekirdi ("If you don't apologize").$t46c$, $t46d$"Take a copy of the contract with you __________ the client asks to see it during the meeting." Burada gerçekleşmesi kesin olmayan bir duruma karşı ÖNCEDEN alınan bir tedbir anlatıldığı için doğru cevap "in case"tir; "if" kullanılsaydı anlam "müşteri isterse o an kopyasını al" gibi mantıksız bir koşula dönüşürdü.$t46d$]),
  ('possessive-s-vs-of', $t47a$'s mi, of mu? Canlı-Cansız Testi$t47a$, $t47b$Sahip olan varlık İNSAN, HAYVAN ya da bir GRUP/KURUM (the government, the company) gibi CANLI/örgütlü bir özne ise iyelik 's tercih edilir ("the manager's decision", "the company's profits"). Sahip olan CANSIZ bir nesne ya da SOYUT bir kavramsa genellikle "of" yapısı tercih edilir ("the roof of the building", "the importance of education") — "the building's roof" gramer olarak yanlış sayılmasa da sınavlarda "of" beklenen doğal tercih olur. Zaman ifadelerinde ("today's newspaper", "a week's holiday") CANSIZ olmasına rağmen 's kullanılır, bu istisnayı ayrıca ezberlemek gerekir. Birden fazla isim art arda sahiplik belirtirken en sona SADECE BİR 's eklenir: "my sister and brother's car" (ortak bir araba) ile "my sister's and brother's cars" (ayrı arabalar) arasındaki fark bu noktada test edilir.$t47b$, ARRAY[$t47c$"__________ main entrance was closed for renovation, so visitors had to use the side door." Sahip olan şey (müze binası) CANSIZ bir yapı olduğu için doğru cevap "The museum's" değil "The entrance of the museum" şeklindeki "of" yapısıdır; soru 'of' tercih edilen bir boşluk içeriyorsa 's seçeneği elenir.$t47c$, $t47d$"__________ latest financial report revealed a significant increase in annual revenue." Sahip olan burada bir KURUM (the company) olduğu için doğru cevap "The company's"tir; kurumlar/canlı örgütler için 's kullanımı doğaldır, "of the company" da gramer olarak doğru olsa da sınavda 's seçeneği bu bağlamda önceliklidir.$t47d$]),
  ('word-formation-collocations', $t48a$Boşluğun Türünü Belirleyip Doğru Eki Seçmek$t48a$, $t48b$Kelime türetme sorularında önce boşluğun cümlede HANGİ GÖREVİ üstlendiğine bak: isimden önce bir sıfat mı gerekiyor, bir fiilden sonra zarf mı gerekiyor, yoksa boşluk özne/nesne konumunda bir isim mi? Bu belirlendikten sonra kökteki kelimeye uygun eki eklemek kolaylaşır: isim yapan ekler (-tion, -ness, -ment, -ity), sıfat yapan ekler (-ful, -less, -able, -ive), zarf yapan ek (-ly), olumsuzluk ekleri (un-, in-, dis-, im-) gibi. Collocation (sık kullanılan kelime eşleşmesi) sorularında ise tek tek kelimelerin anlamından çok, hangi kelimelerin DOĞAL OLARAK birlikte kullanıldığına bak — "make a decision" doğrudur ama "do a decision" İngilizcede kullanılmaz, bu bir gramer kuralı değil, YERLEŞİK bir alışkanlıktır ve ezbere dayanır.$t48b$, ARRAY[$t48c$"The committee's __________ to postpone the project disappointed many investors." Boşluk "The committee's" iyelik ekinden sonra bir İSİM gerektirdiği için doğru cevap "decision"dır; "decide" (fiil) ya da "decisive" (sıfat) bu konumda kullanılamaz.$t48c$, $t48d$"It is __________ to ignore the long-term environmental effects of such industrial projects." Boşluk "It is ___ to" kalıbında bir SIFAT gerektirdiği için doğru cevap "irresponsible"dır ("responsibility" isim, "irresponsibly" zarf olduğu için elenir); olumsuzluk öneki "ir-" burada "responsible" kökünün "r" ile başlamasına uyum sağlar.$t48d$]),
  ('must-vs-have-to', $t49a$must / have to: Zorunluluğun Kaynağına Bak$t49a$, $t49b$Zorunluluk konuşmacının KENDİ GÖRÜŞÜNDEN, kişisel bir gerekliliğinden doğuyorsa "must" kullanılır ("I must call my mother" — bunu ben öyle hissettiğim için yapmalıyım); zorunluluk DIŞARIDAN gelen bir kural, otorite ya da durumdan doğuyorsa "have to" kullanılır ("I have to wear a uniform at work" — işyeri kuralı, kendi fikrim değil). Bu ayrım özellikle OLUMSUZ formda kritik bir anlam farkına dönüşür: "mustn't" bir şeyin YASAK olduğunu anlatır ("You mustn't smoke here" = yasak), "don't have to" ise bir şeyin yapılmasının GEREKMEDİĞİNİ anlatır ama yapılması serbesttir ("You don't have to come if you're busy" = gelmen şart değil, istersen gel). Geçmiş zamanda "must" kullanılamaz, zorunlu olarak "had to" kullanılır — bu YDS'nin sık sorduğu bir zaman tuzağıdır.$t49b$, ARRAY[$t49c$"All passengers __________ fasten their seatbelts before the plane takes off — it's airline policy." Zorunluluk havayolu şirketinin DIŞARIDAN koyduğu bir kural olduğu için doğru cevap "have to"dur; "must" burada da kabul edilebilir olsa da, kuralın kaynağı resmi bir otorite olduğu için sınavlarda "have to" tercih edilen cevaptır.$t49c$, $t49d$"When I was a child, we __________ finish all our homework before watching television." Cümle GEÇMİŞ zamanda olduğu için "must" kullanılamaz, doğru cevap "had to"dur; bu, "must"ın geçmiş zaman formunun bulunmadığının klasik bir test şeklidir.$t49d$]),
  ('neednt-vs-mustnt', $t50a$needn't mü, mustn't mü? Yasak-Gereksizlik Ayrımı$t50a$, $t50b$needn't (= don't/doesn't need to) bir eylemin yapılmasının GEREKMEDİĞİNİ ama yapılmasının YASAK olmadığını anlatır — kişi isterse yine de yapabilir. mustn't ise bir eylemin KESİNLİKLE YASAK olduğunu, yapılmaması gerektiğini anlatır. Cümlede "it's not necessary", "there's no need", "you're free to... but" gibi ifadeler varsa needn't; "it's forbidden", "not allowed", "strictly prohibited" gibi ifadeler varsa mustn't doğru cevaptır. Ayrıca needn't have + V3 yapısı, geçmişte YAPILMASI GEREKMEYEN ama YAPILMIŞ bir eylemi anlatır (gereksiz çaba); bu, mustn't have + V3 (bir şeyin yapılmamış olması gerektiğine dair çıkarım) ile karıştırılmamalıdır.$t50b$, ARRAY[$t50c$"You ___ bring your own laptop; the company provides one for every employee." Şirketin zaten bilgisayar sağlaması, kendi laptopunu getirmenin GEREKMEDİĞİNİ (ama getirebileceğini) gösterir → doğru cevap "needn't"tür, "mustn't" değildir çünkü getirmek yasak değildir.$t50c$, $t50d$"Visitors ___ touch the exhibits; it is strictly prohibited to protect the artifacts." Cümledeki "strictly prohibited" ifadesi kesin bir yasağı belirtir → doğru cevap "mustn't"tür; "needn't" burada yanlıştır çünkü sadece gereksizliği değil, yasağı anlatan bir ifade kullanılmıştır.$t50d$]),
  ('on-time-in-time', $t51a$on time / in time: Tam Saatinde mi, Yetişerek mi?$t51a$, $t51b$"on time" planlanan/beklenen TAM SAATTE gerçekleşmeyi anlatır (geç kalmamak, programa uymak) — tren, toplantı, uçuş gibi bir ZAMAN ÇİZELGESİYLE ilişkilidir. "in time" ise bir şey olmadan/çok geç olmadan ÖNCE yetişmeyi anlatır, genellikle "for + isim" veya "to + fiil" ile bir SONUÇLA birlikte kullanılır ("in time for the meeting", "in time to catch the bus"). Cümlede sabit bir saat/program ("the flight departs at...", "punctual") vurgusu varsa on time; bir şeyi kaçırmamak/yetişmek vurgusu ("just in time", "before it was too late") varsa in time doğru cevaptır.$t51b$, ARRAY[$t51c$"The train left exactly ___, so all the passengers who arrived a minute late missed it." Cümledeki "exactly" ve belirli bir saate uyma vurgusu, sabit bir programı işaret eder → doğru cevap "on time"dır.$t51c$, $t51d$"We arrived at the hospital just ___ to see the newborn baby before visiting hours ended." "just... before" yapısı, bir şey olmadan HEMEN ÖNCE yetişmeyi anlatır, sabit bir saatten değil bir sondan bahsedilir → doğru cevap "in time"dır.$t51d$]),
  ('one-ones-substitution', $t52a$Tekrar Etmeden İşaret Etmek: one / ones Taktiği$t52a$, $t52b$Cümlede daha önce geçen SAYILABİLEN bir isim tekrar edilmeyecekse, o ismin yerine tekilse "one", çoğulsa "ones" kullanılır — bu zamir SIFATLARLA birlikte kullanılabilir ("the red one", "the expensive ones") ama SAYILAMAYAN isimlerin yerine KULLANILMAZ. Boşluktan önce "this/that/these/those/the/a/an + sıfat" gibi bir belirteç varsa ve ardından önceden bahsedilen bir isim tekrarlanacaksa one/ones güçlü bir adaydır; isim sayılamıyorsa veya zamir zaten nesnenin KENDİSİNİ (it/them) işaret ediyorsa one/ones yanlıştır.$t52b$, ARRAY[$t52c$"I don't like this jacket; could you show me a cheaper ___?" "jacket" sayılabilen, tekil bir isim ve tekrar edilmemesi gerekiyor → doğru cevap "one"dur.$t52c$, $t52d$"These shoes are too tight; do you have any larger ___?" "shoes" çoğul olduğu için → doğru cevap "ones"tur, "one" tekil olduğu için burada yanlıştır.$t52d$]),
  ('gerund-as-subject-object', $t53a$-ing'in İsim Gibi Davranması: Gerund Taktiği$t53a$, $t53b$Bir -ing formu cümlede ÖZNE konumunda (cümlenin başında, tekil fiil alarak) veya fiilin NESNESİ konumunda ise, bu bir gerund'dur ve isim gibi davranır: "Smoking is bad for your health" (özne), "I enjoy reading" (nesne). Bazı fiiller (enjoy, avoid, mind, suggest, finish, admit, deny, practice) kesinlikle sadece gerund alır, asla to-infinitive almaz — boşluktan önce bu fiillerden biri varsa "to + fiil" şıkkı doğrudan elenir. Bir edattan (in, by, without, after, before) sonra gelen fiil de her zaman -ing formundadır, çünkü edatlardan sonra isim soylu bir yapı gelir.$t53b$, ARRAY[$t53c$"___ a new language requires patience and daily practice." Cümlenin öznesi olan ve tekil fiil ("requires") alan bir -ing yapısı gerekir → doğru cevap "Learning"dir.$t53c$, $t53d$"She admitted ___ the documents without her manager's approval." "admit" fiilinden sonra kesinlikle gerund gelir, to-infinitive gelemez → doğru cevap "signing"dir, "to sign" seçeneği bu kuralı ihlal ettiği için elenir.$t53d$]),
  ('past-perfect-continuous', $t54a$had been + -ing: Geçmişte Süren Eylemi Yakalamak$t54a$, $t54b$Past Perfect Continuous (had been + V-ing), geçmişte belirli bir ANDAN ÖNCE BAŞLAYIP O ANA KADAR DEVAM ETMİŞ bir eylemin SÜRESİNİ vurgulamak için kullanılır — cümlede genellikle "for + süre" veya "since + başlangıç noktası" ifadesi ve bu sürenin SONUNDA gerçekleşen başka bir geçmiş olay (past simple) birlikte bulunur. Sadece bir eylemin diğerinden ÖNCE tamamlanmış OLMASI (süreç değil, sonuç) vurgulanıyorsa düz Past Perfect (had + V3) yeterlidir; cümlede "for/since" ile birlikte bir süre vurgusu varsa had been + -ing tercih edilir.$t54b$, ARRAY[$t54c$"She ___ (study) for six hours when her computer suddenly crashed." "for six hours" süre ifadesi ve bu sürenin SONUNDA gerçekleşen ani bir olay ("crashed") birlikte kullanıldığı için → doğru cevap "had been studying"dir.$t54c$, $t54d$"By the time the fire department arrived, the flames ___ (destroy) most of the building." Burada bir süreç değil, bir olayın başka bir olaydan ÖNCE TAMAMLANMIŞ OLMASI (sonuç) vurgulanıyor → doğru cevap "had destroyed"tür, "had been destroying" değildir çünkü yangının binayı yok etmiş olması bir sonuçtur, süren bir eylem değil.$t54d$]),
  ('past-perfect', $t55a$İki Geçmiş Arasında Önce-Sonra Sıralaması$t55a$, $t55b$Bir cümlede İKİ farklı geçmiş zaman eylemi varsa ve bunlardan biri DİĞERİNDEN ÖNCE gerçekleşmişse, daha ÖNCE olan eylem had + past participle (Past Perfect), daha SONRA olan ise Past Simple ile anlatılır. Cümlede "before", "after", "by the time", "already", "when" gibi sıralama belirten kelimeler varsa, bu kelimelere bakarak hangi eylemin önce olduğunu belirle: "before/by the time X happened" ifadesinden önce yaşanan eylem had + V3 alır. İki eylem AYNI ANDA veya ART ARDA (önce-sonra ayrımı olmadan) gerçekleşiyorsa her ikisi de Past Simple kalır, Past Perfect kullanmaya gerek yoktur.$t55b$, ARRAY[$t55c$"When I arrived at the station, the train ___ (already/leave)." Trenin benim varışımdan ÖNCE kalkmış olması gerekiyor → doğru cevap "had already left"tir.$t55c$, $t55d$"When I arrived at the station, I ___ (buy) a ticket and ___ (board) the train." Burada biletin alınması ve trene binilmesi varıştan SONRA, ART ARDA gerçekleşen eylemler → doğru cevap düz Past Simple'dır ("bought... boarded"), Past Perfect gerekmez çünkü bu eylemler varıştan önce değil sonra olmuştur.$t55d$]),
  ('present-simple-vs-continuous', $t56a$Alışkanlık mı, Şu An mı? Sinyal Kelimelere Bak$t56a$, $t56b$Present Simple, GENEL GERÇEKLERİ, ALIŞKANLIKLARI ve DÜZENLİ TEKRARLANAN eylemleri anlatır ve genellikle "always, usually, often, every day, on Mondays" gibi sıklık zarflarıyla birlikte gelir. Present Continuous ise ŞU AN KONUŞMA ANINDA veya BU DÖNEMDE (geçici olarak) süren bir eylemi anlatır ve "now, at the moment, these days, currently, still" gibi ifadelerle birlikte gelir. Durum fiilleri (know, believe, like, love, hate, want, own, belong, understand) DUYGU/DÜŞÜNCE/SAHİPLİK bildirdiği için normalde -ing ALMAZ, sürekli olsalar bile Present Simple ile kullanılır — bir boşlukta bu fiillerden biri varsa "-ing" şıkkı doğrudan elenir.$t56b$, ARRAY[$t56c$"Water ___ (boil) at 100 degrees Celsius at sea level." Bu evrensel, değişmeyen bir bilimsel gerçek → doğru cevap "boils"tur (Present Simple).$t56c$, $t56d$"I know you're busy, but I really ___ (need) your help with this report right now." "need" bir durum fiilidir (ihtiyaç/istek bildirir) ve "right now" ifadesine rağmen -ing ALAMAZ → doğru cevap "need"dir, "am needing" yanlıştır.$t56d$]),
  ('quite-rather-fairly', $t57a$quite'in İki Yüzü: Derecelenebilir mi, Mutlak mı?$t57a$, $t57b$"fairly" ve "rather" sıfat/zarfın yoğunluğunu "oldukça" anlamında hafifçe artırır; "rather" genellikle BEKLENENDEN FAZLA veya OLUMSUZ bir tonla kullanılır ("rather expensive" = beklenenden pahalı), "fairly" ise daha nötr ve ORTA DÜZEY bir dereceyi belirtir. "quite" ise İKİ FARKLI anlamda kullanılabilir: DERECELENEBİLEN sıfatlarla (big, good, cold) "oldukça" anlamına gelirken, MUTLAK/DERECELENEMEYEN sıfatlarla (perfect, impossible, amazing, certain, right) "tamamen" anlamına gelir — bir boşlukta "quite" seçeneği varsa, sıfatın derecelenebilir mi yoksa mutlak mı olduğuna bakarak anlamı belirlemek gerekir, bu ayrımı atlamak YDS'de klasik bir tuzaktır.$t57b$, ARRAY[$t57c$"The hotel room was ___ small for the price we paid, which disappointed us." Beklenenden daha olumsuz bir ton ve hafif bir eleştiri var → doğru cevap "rather"dır.$t57c$, $t57d$"His explanation of the theory was ___ perfect; I couldn't find a single flaw in it." "perfect" derecelenemeyen (mutlak) bir sıfattır, bu yüzden buradaki "quite" "oldukça" değil "tamamen" anlamına gelir → doğru cevap "quite"tır; "fairly" burada kullanılamaz çünkü "fairly perfect" mutlak bir sıfatla çelişen garip bir ifadedir.$t57d$]),
  ('dependent-prepositions', $t58a$Sabit Edat Kalıplarını Ezbere Tanımak$t58a$, $t58b$Birçok sıfat ve fiil, belirli bir edatla SABİT bir kalıp oluşturur ve bu kalıp Türkçedeki edat mantığıyla ÖRTÜŞMEZ, bu yüzden anlamdan değil EZBERDEN çözülmelidir: "good AT" (bir konuda iyi), "interested IN" (bir şeyle ilgili), "afraid OF" (bir şeyden korkan), "responsible FOR" (bir şeyden sorumlu), "depend ON" (bir şeye bağlı), "insist ON" (bir konuda ısrar eden), "succeed IN" (bir konuda başarılı olan), "apologize FOR" (bir şey için özür dileyen). Bir boşlukta sıfat/fiil + edat kalıbı aranıyorsa, önce o sıfat/fiilin HANGİ EDATLA sabitlendiğini hatırlamak gerekir — Türkçe çeviriye güvenmek (ör. "ilgilenmek" kelimesinin "ile" ekini "with" olarak çevirmeye çalışmak, oysa doğrusu "interested IN"dir) klasik bir hata kaynağıdır.$t58b$, ARRAY[$t58c$"She has always been extremely good ___ solving complex mathematical problems." "good" sıfatından sonra sabit olarak "at" edatı gelir → doğru cevap "at"tır.$t58c$, $t58d$"The manager is directly responsible ___ any delays in the delivery schedule." "responsible" sıfatından sonra sabit olarak "for" edatı gelir → doğru cevap "for"dur, Türkçe "sorumlu" kelimesinden yola çıkarak başka bir edat (ör. "of") seçmek yanlış olur.$t58d$]),
  ('so-neither-agreement', $t59a$so / neither ile Kısa Katılma Cümleleri Kurmak$t59a$, $t59b$Bir önceki cümledeki durumla AYNI FİKİRDE/DURUMDA olunduğunu kısaca belirtmek için, önceki cümle OLUMLU ise "so + yardımcı fiil + özne" ("So do I", "So is she"), önceki cümle OLUMSUZ ise "neither/nor + yardımcı fiil + özne" ("Neither do I", "Nor does he") kalıbı kullanılır — bu yapılarda yardımcı fiil ÖZNEDEN ÖNCE gelir (devrik yapı) ve kullanılan yardımcı fiil, önceki cümledeki fiile göre (be/do/have/modal) SEÇİLMELİDİR. "So I do" veya "Neither I do" gibi devrik olmayan yapılar yanlıştır; ayrıca önceki cümle olumluyken "neither" kullanmak veya olumsuzken "so" kullanmak anlam açısından çelişki yaratır ve kesinlikle yanlıştır.$t59b$, ARRAY[$t59c$A: "I've never been to Japan." B: "___ have I." Önceki cümle OLUMSUZ ("never been") olduğu için aynı durumu paylaşan katılma ifadesi "neither" ile kurulur → doğru cevap "Neither"dır.$t59c$, $t59d$A: "My sister can speak three languages fluently." B: "___ can my brother." Önceki cümle OLUMLU olduğu için aynı yeteneği paylaşan katılma ifadesi "so" ile kurulur → doğru cevap "So"dur; "Neither" burada anlam çelişkisi yaratacağı için kesinlikle yanlıştır.$t59d$]),
  ('some-any-no-none', $t60a$some/any/no/none Seçiminde Cümle Tipine Bakmak$t60a$, $t60b$Önce cümlenin OLUMLU mu, OLUMSUZ/SORU mu olduğuna bak: olumlu cümlelerde "some" kullanılır ("I have some books"); olumsuz ve soru cümlelerinde "any" kullanılır ("I don't have any books" / "Do you have any books?"). İSTİSNA: bir şey teklif ederken veya rica ederken soru cümlesinde bile "some" kullanılır çünkü olumlu bir cevap beklenir ("Would you like some coffee?"). "no" doğrudan isimden önce gelir ve cümleyi TEK BAŞINA olumsuz yapar — bu yüzden "no" ile birlikte ayrıca "not" veya başka bir olumsuzluk sözcüğü KULLANILMAZ ("I don't have no money" YANLIŞTIR, ya "I don't have any money" ya da "I have no money" olmalıdır — bu YDS'nin klasik çifte olumsuzluk tuzağıdır). "none" ise bir isim grubunun yerine geçer ve genellikle "none of + the/my/these" kalıbıyla belirli bir grubun HİÇBİRİNİ ifade eder ("None of the students passed").$t60b$, ARRAY[$t60c$"__________ of the committee members objected to the new proposal during the meeting." Boşluktan sonra "of the committee members" (belirli bir grup + of) geldiği için doğru cevap "None"dur; "No" buraya gelemez çünkü "no" doğrudan isimden önce gelir, "of" ile kullanılmaz.$t60c$, $t60d$"I didn't get __________ useful feedback from the reviewers." Cümle olumsuz ("didn't") olduğu için doğru cevap "any"dir; "I didn't get no useful feedback" şeklinde hem "didn't" hem "no" kullanmak çifte olumsuzluk hatasıdır ve YDS'de her zaman yanlış şıktır.$t60d$]),
  ('question-word-order', $t61a$Soru Cümlesinde Yardımcı Fiili ve Kelime Sırasını Takip Etmek$t61a$, $t61b$Doğrudan bir soru cümlesinde kelime sırası SORU KELİMESİ (varsa) + YARDIMCI FİİL/MODAL + ÖZNE + ANA FİİL şeklindedir ("Where did she go?", "What can he do?"). Ancak bu cümle BAŞKA BİR CÜMLENİN İÇİNE (dolaylı/gömülü soru) girdiğinde kelime sırası DÜZ CÜMLE sırasına (ÖZNE + YÜKLEM) döner ve "do/does/did" yardımcı fiili TAMAMEN DÜŞER — "I wonder where she went" doğrudur, "I wonder where did she go" YANLIŞTIR. Bu, YDS'nin "Could you tell me...", "I don't know...", "I wonder..." gibi ifadelerle başlayan cümlelerde en sık kurduğu tuzaktır: şıklarda ters çevrilmiş (inverted) bir yapı görürsen ve bu yapı "tell me/wonder/know" gibi bir ifadenin İÇİNDEYSE, o şık kesinlikle yanlıştır.$t61b$, ARRAY[$t61c$"Could you tell me __________?" seçeneklerinden "where is the nearest bank" değil, "where the nearest bank is" doğru cevaptır — çünkü soru "Could you tell me" ifadesinin içine gömülmüştür ve düz cümle sırasına dönmelidir.$t61c$, $t61d$"__________ to the party last night?" bağımsız bir soru cümlesi olduğu için burada normal soru devrik sırası geçerlidir, doğru cevap "Who did you invite"dır; bu cümle "I wonder" gibi bir ifadenin içine girseydi ("I wonder who you invited to the party"), devrik yapı kaybolurdu.$t61d$]),
  ('question-tags', $t62a$Question Tag'de Zıtlık ve Yardımcı Fiil Eşleşmesi$t62a$, $t62b$Question tag kuralının temeli ZITLIK: ana cümle OLUMLU ise etiket OLUMSUZ, ana cümle OLUMSUZ ise etiket OLUMLUdur ("She is tired, isn't she?" / "She isn't tired, is she?"). Etiketteki yardımcı fiil ana cümledeki yardımcı fiille/modal ile AYNI OLMAK ZORUNDADIR ("They have finished, haven't they?"); ana cümlede yardımcı fiil/modal YOKSA (yalın present/past simple), etikette do/does/did kullanılır ("He plays football, doesn't he?"). Sık çıkan istisnalar: "I am" cümlesinin etiketi düzensiz olarak "aren't I"dir ("amn't I" DEĞİL); emir cümlelerinin etiketi genellikle "will you"dur; "Let's" ile başlayan tekliflerin etiketi "shall we"dir; "there is/are" cümlelerinde özne yerine "there" tekrar edilir ("There isn't any milk left, is there?").$t62b$, ARRAY[$t62c$"You haven't finished your homework yet, __________?" Ana cümle olumsuz ("haven't") olduğu için etiket olumlu olmalı ve aynı yardımcı fiili kullanmalı → doğru cevap "have you"dur, "haven't you" değildir.$t62c$, $t62d$"Let's go for a walk, __________?" "Let's" ile başlayan tekliflerde standart kural (özne+yardımcı fiil zıtlığı) uygulanmaz, sabit kalıp "shall we" kullanılır — "don't we" gibi bir cevap burada her zaman yanlıştır.$t62d$]),
  ('adverbs-of-manner-formation', $t63a$-ly Zarf Yapımında Düzensizleri ve Sıfat-Zarf Çakışmalarını Yakalamak$t63a$, $t63b$Tarz zarfları genelde sıfat + "-ly" ile oluşur (quick → quickly), ama şıklarda üç tip tuzak çıkar: (1) yazım değişimi gerektiren sıfatlar — "-y" ile bitenler "-ily" olur (happy → happily), "-le" ile bitenler sadece "-ly" olur (simple → simply), "-ic" ile bitenler "-ically" olur (basic → basically); (2) düzensiz zarflar — "good"un zarfı "well"dir ("goodly" YOKTUR), "fast/hard/late/early/straight" gibi kelimelerin zarf hali sıfatla AYNIDIR ("He runs fast", "fastly" diye bir kelime yoktur); (3) EN SIK TUZAK — bazı kelimelerin "-ly'li" hali TAMAMEN FARKLI bir anlam taşır: "hard" (çok/sıkı) ile "hardly" (neredeyse hiç, güçlükle) birbirinin zıttı gibi davranır, "late" (geç) ile "lately" (son zamanlarda) de aynı tuzağı kurar — cümlenin anlamına bakmadan sadece "-ly" ekleyip cevap vermek bu sorularda neredeyse her zaman yanlış şıkkı seçtirir.$t63b$, ARRAY[$t63c$"She worked so __________ that she finished the project a week early." Burada "çok/yoğun biçimde çalıştı" anlamı gerektiği için doğru cevap "hard"tır (zarf hali sıfatla aynı); "hardly" (neredeyse hiç) kullanmak cümlenin anlamını tam tersine çevirir ve yanlıştır.$t63c$, $t63d$"He __________ had time to say goodbye before the train left." Burada "neredeyse hiç vakti olmadı" anlamı gerektiği için doğru cevap "hardly"dir; "hard" kullanmak burada anlamsız ve gramer açısından yanlıştır çünkü "had" bir sıfat değil fiildir ve zarfa ihtiyaç duyar.$t63d$]),
  ('the-specific-vs-general', $t64a$the Kullanıp Kullanmama Testi: Ortak Bilgi mi, Genel Kategori mi?$t64a$, $t64b$"the" kullanımı KARŞILIKLI BİLİNEN/TANIMLANMIŞ bir şeye işaret eder: bir isim daha önceki cümlede "a/an" ile tanıtıldıysa ikinci bahsedilişinde "the" alır ("I bought a car. The car is red."), ya da isim dünyada TEK olan bir şeyse ("the sun", "the internet") ya da bir sıfat öbeği/ilgi cümleciğiyle BELİRLİ hale getirilmişse ("the book ON THE TABLE") "the" kullanılır. Buna karşılık bir isim GENEL BİR KATEGORİYİ veya kavramı temsil ediyorsa (çoğul sayılabilen veya sayılamayan isimlerle) ARTİKEL KULLANILMAZ ("Books are expensive" = genel olarak kitaplar, "The books are expensive" = BELİRLİ bir kitap grubu). En üstünlük sıfatları ("the best"), sıra sayıları ("the first") ve bazı sabit coğrafi isimler (nehirler, okyanuslar: "the Nile") her zaman "the" ister — bunlar ezberlenmesi gereken istisnalardır.$t64b$, ARRAY[$t64c$"__________ information you gave me yesterday turned out to be incorrect." "you gave me yesterday" ilgi cümleciği ismi BELİRLİ hale getirdiği için doğru cevap "The"dir (artikelsiz bırakmak yanlıştır, çünkü artık genel bir bilgi değil, belirli bir bilgiden bahsediliyor).$t64c$, $t64d$"__________ information is power in today's digital world." Burada genel olarak "bilgi" kavramından (herhangi bir belirli bilgi değil) bahsedildiği için doğru cevap artikelsiz bırakmaktır ("Information is power..."), "The information" kullanmak buradaki genel-geçer anlamı bozar.$t64d$]),
  ('used-to-be-used-to', $t65a$used to / be used to / get used to: Fiil mi, Alışkanlık mı?$t65a$, $t65b$Üç yapı birbirine çok benzer ama tamamen farklı anlamlar taşır: "used to + YALIN FİİL" geçmişte YAPILIP artık yapılmayan bir alışkanlığı anlatır ve SADECE geçmiş zamanda kullanılır ("I used to smoke" = eskiden sigara içerdim, artık içmiyorum); "be used to + İSİM/-ing" ŞU ANDA bir duruma ALIŞKIN OLMAYI anlatır ("I am used to working at night" = gece çalışmaya alışkınım); "get used to + İSİM/-ing" ise bir duruma ALIŞMA SÜRECİNİ anlatır ("I am getting used to the new schedule" = yeni programa alışıyorum). En sık tuzak: "used to" sonrası YALIN FİİL gelirken, "be/get used to" sonrası HER ZAMAN -ing veya isim gelir, asla yalın fiil gelmez ("I am used to work" YANLIŞTIR, doğrusu "I am used to working"tır).$t65b$, ARRAY[$t65c$"When I was a child, I __________ (walk) to school every day, but now I take the bus." Geçmişte yapılıp artık yapılmayan bir alışkanlık anlatıldığı için doğru cevap "used to walk"tır, "was used to walking" değildir.$t65c$, $t65d$"After six months in Berlin, she __________ (live) alone, so moving back with her parents felt strange." Burada geçmişte bir duruma ALIŞKIN HALE GELMİŞ olma anlatıldığı için doğru cevap "was used to living"tir (be used to + -ing); "used to live" kullanmak burada "eskiden yaşardı ama artık yaşamıyor" gibi yanlış bir anlam katar.$t65d$]),
  ('wish-if-only', $t66a$wish/if only ile Zaman Bir Basamak Geri Kayar$t66a$, $t66b$wish ve if only, gerçek durumun TERSİNİ dilemek için kullanılır ve fiil zamanı gerçek zamandan BİR BASAMAK GERİYE kayar: ŞİMDİKİ bir durumdan memnuniyetsizlik için "wish/if only + PAST SIMPLE" kullanılır ("I wish I knew the answer" = şu an bilmiyorum ama bilmeyi isterdim; "be" fiili için her özneyle "were" kullanılır, "was" değil); GEÇMİŞE dönük bir pişmanlık için "wish/if only + PAST PERFECT" kullanılır ("I wish I had studied harder" = geçmişte çalışmadım, pişmanım); GELECEKTE bir şeyin değişmesini dilemek veya birinin davranışından RAHATSIZLIK duymak için "wish/if only + WOULD" kullanılır ("I wish you would stop interrupting me"). "will/can/must" gibi yapıları doğrudan wish'ten sonra kullanmak her zaman yanlıştır.$t66b$, ARRAY[$t66c$"I wish I __________ (be) taller so I could reach the top shelf." Şu anki bir durumdan (boyunun kısa olması) memnuniyetsizlik anlatıldığı için doğru cevap "were"dir, "am" veya "will be" değildir.$t66c$, $t66d$"If only I __________ (apologize) to her before she left the country last year." Geçmişte yapılmamış bir eylem için pişmanlık anlatıldığı için doğru cevap "had apologized"tır (past perfect); "apologized" (sadece past simple) burada yanlıştır çünkü dilek şimdiki değil geçmiş bir duruma yöneliktir.$t66d$]),
  ('prepositions-place', $t67a$Yer Edatlarında Nokta-Yüzey-Hacim Testi$t67a$, $t67b$Yer edatı seçerken ismin TÜRÜNE bak: isim bir NOKTA/konum olarak düşünülüyorsa (adres, durak, belirli bir nokta) "at" kullanılır ("at the bus stop", "at the corner"); isim bir YÜZEY ise "on" kullanılır ("on the table", "on the wall"); isim bir HACİM/ALAN içindeyse (kapalı bir mekan, şehir, ülke, kutu) "in" kullanılır ("in the room", "in London", "in the box"). Aynı kelime bağlama göre farklı edat alabilir: "at school" (okulda, genel olarak eğitim faaliyeti) ile "in the school" (okul binasının fiziksel içinde) farklı şeyler anlatır — YDS bu ince farkı sıkça kullanır. "at the corner of the street" (sokağın köşesinde, dışarıdan) ile "in the corner of the room" (odanın köşesinde, kapalı alan içinde) karşılaştırması da klasik bir tuzaktır.$t67b$, ARRAY[$t67c$"She was waiting __________ the bus stop when it started to rain." Otobüs durağı bir NOKTA/konum olarak düşünüldüğü için doğru cevap "at"tır; "in" veya "on" burada yanlıştır.$t67c$, $t67d$"The committee placed a small plaque __________ the wall to commemorate the founder." Duvar bir YÜZEY olduğu için doğru cevap "on"dur; aynı cümlede "the room" kullanılsaydı (kapalı bir hacim), doğru edat "in" olurdu.$t67d$]),
  ('reflexive-pronouns', $t68a$Dönüşlü Zamir mi, Kişi Zamiri mi? Özne=Nesne Testi$t68a$, $t68b$Dönüşlü zamir (myself, yourself, himself, herself, itself, ourselves, yourselves, themselves) SADECE eylemi yapan ile eylemden etkilenen kişi AYNI olduğunda kullanılır ("He cut himself while cooking" = kendini kesti, kesen ve kesilen aynı kişi). Özne ile nesne FARKLI kişilerse normal kişi zamiri (him, her, them...) kullanılır — "He cut him" demek, BAŞKA birini kestiği anlamına gelir, bu yüzden özneyle nesnenin aynı kişi olup olmadığını cümlenin anlamından çıkarmak gerekir. Ayrıca dönüşlü zamirler VURGU amacıyla da kullanılır, "bizzat, kendisi" anlamında ("I did it myself" = bunu bizzat ben yaptım, başkası yapmadı) — bu kullanımda zamir gramatik olarak ZORUNLU değildir, cümleden çıkarılabilir, sadece vurgu katar.$t68b$, ARRAY[$t68c$"The manager blamed __________ for the project's failure, even though the mistake was not his fault." Yöneticinin KENDİSİNİ suçladığı (özne=nesne) anlatıldığı için doğru cevap "himself"tir; "him" kullanmak başka bir erkeği suçladığı anlamına gelir ki bu cümlenin bağlamıyla çelişir.$t68c$, $t68d$"I didn't hire an assistant; I handled all the paperwork __________." Burada "bizzat kendim" vurgusu yapıldığı için doğru cevap "myself"tir ve cümleden çıkarılsa bile cümle gramatik olarak doğru kalır, sadece vurgu kaybolur.$t68d$])
